import { injectable } from 'tsyringe-neo'
import { and, eq, inArray, isNull } from 'drizzle-orm'
import { DrizzleClient } from '@bk-dash/core-typescript'
import { productCosts } from '@bk-dash/contracts/db'
import type { QuantityModifier } from '@bk-dash/contracts-typescript/wire/enums'
import { ApplicableProductCostSchema, ApplicableProductCostItemSchema } from './ApplicableProductCost'
import type { ApplicableProductCost } from './ApplicableProductCost'
import { ProductCostQueryService, type FindApplicableProductCostsInput } from './ProductCostQueryService'
import { Timeline } from '../../../shared/objects/Timeline'

/** Serialized shape of a MonetaryAmount after JSONB round-trip. */
interface StoredMonetaryAmount {
	amountCents: number
	currency: string
}

/** Serialized shape of a ProductCostOptionItem after JSONB round-trip.
 *  Id.toJSON() → raw UUID string; MonetaryAmount.toJSON() → {amountCents, currency}. */
interface StoredProductCostOptionItem {
	id: string
	variantIds: string[]
	quantity: number
	quantityModifier: QuantityModifier
	unitCost: StoredMonetaryAmount
	variantsHash: string
}

/** Serialized shape of a value window within a ProductCostOption after JSONB round-trip. */
interface StoredProductCostOptionValue {
	startDate: string
	endDate?: string | null
	items: StoredProductCostOptionItem[]
}

/** Serialized shape of a ProductCostOption after JSONB round-trip (new keyed-values shape). */
interface StoredProductCostOption {
	id: string
	currency: string
	country?: string
	values: StoredProductCostOptionValue[]
}

@injectable()
export class DrizzleProductCostQueryService extends ProductCostQueryService {
	constructor(private readonly db: DrizzleClient) {
		super()
	}

	async findApplicable(input: FindApplicableProductCostsInput): Promise<ApplicableProductCost[]> {
		const filters = [eq(productCosts.storeId, input.storeId), isNull(productCosts.deletedAt)]
		if (input.productIds && input.productIds.length > 0) {
			filters.push(inArray(productCosts.productId, input.productIds))
		}
		const rows = await this.db
			.select()
			.from(productCosts)
			.where(and(...filters))

		const out: ApplicableProductCost[] = []
		for (const row of rows) {
			const options = (row.options as StoredProductCostOption[]) ?? []
			for (const option of options) {
				// Coerce stored ISO strings to Date before Timeline (z.coerce.date path)
				const entries = option.values.map(v => ({
					...v,
					startDate: new Date(v.startDate),
					endDate: v.endDate ? new Date(v.endDate) : null,
				}))
				const active = input.at ? new Timeline(entries).activeAt(input.at) : new Timeline(entries).current()
				if (!active) continue
				const data = active.items.map(item =>
					ApplicableProductCostItemSchema.parse({
						cost: item.unitCost.amountCents,
						costOptionItemId: item.id,
						currency: item.unitCost.currency,
						productId: row.productId ?? undefined,
						quantity: item.quantity,
						quantityModifier: item.quantityModifier,
						variants: item.variantIds,
					}),
				)
				out.push(
					ApplicableProductCostSchema.parse({
						costId: row.id,
						costOptionId: option.id,
						type: row.costType,
						country: option.country,
						startDate: active.startDate,
						endDate: active.endDate,
						data,
						productId: row.productId ?? undefined,
						variants: data.flatMap(d => d.variants ?? []),
					}),
				)
			}
		}
		return out
	}
}

import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import {
	OperationalCostCategory,
	OperationalCostFlow,
	OperationalCostPaymentStatus,
	OperationalCostRecurrency,
	type CurrencyCode,
} from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmount } from '../../shared/objects'
import type { FinanceDomainErrors } from '../errors'
import { countOccurrencesInRange, occurrenceWindow } from './recurrence'

export const StatusOverrideSchema = z.object({
	occurrenceDate: z.date(),
	status: z.enum(OperationalCostPaymentStatus),
})

export const OperationalCostSchema = z.object({
	storeId: z.instance(Id),
	category: z.enum(OperationalCostCategory),
	// Cash-flow direction: DEBIT = money out (a cost), CREDIT = money in.
	flow: z.enum(OperationalCostFlow),
	description: z.string().min(1).max(500),
	amount: z.instance(MonetaryAmount).refine(m => m.amountCents > 0, {
		error: 'INVALID_AMOUNT' as FinanceDomainErrors,
	}),
	recurrency: z.enum(OperationalCostRecurrency),
	startDate: z.date(),
	endDate: z.date().nullable(),
	// Sparse deviations from the default per-occurrence status — NOT the
	// full occurrence set. Occurrences are derived at runtime; this only
	// records the ones the merchant flipped away from DEFAULT_OCCURRENCE_STATUS.
	statusOverrides: z.array(StatusOverrideSchema).default([]),
	deletedAt: z.date().nullable(),
})

export type OperationalCostProps = Z.infer<typeof OperationalCostSchema>

export interface OperationalCostOccurrence {
	occurrenceDate: Date
	status: OperationalCostPaymentStatus
}

/**
 * `OperationalCost` aggregate per spec § BC8 Finance. Recurrent or
 * one-off business expense (rent, employee salary, software, etc).
 *
 * Occurrences are **derived at runtime** from `(recurrency, startDate,
 * endDate)` — never stored. Every derived occurrence carries
 * `DEFAULT_OCCURRENCE_STATUS` (PAID) unless `statusOverrides[]` records a
 * deviation for that date. Resolution is therefore **by exclusion**: the
 * full series minus the overridden dates, rather than summing stamped rows.
 *
 * Soft-deleted by `delete()`: row preserved so historical analytics
 * keep their context.
 */
export class OperationalCost extends AggregateRoot<typeof OperationalCostSchema> {
	static override schema = OperationalCostSchema

	/** Status every derived occurrence carries until a `statusOverride` says otherwise. */
	static readonly DEFAULT_OCCURRENCE_STATUS = OperationalCostPaymentStatus.PAID

	/** Cash-flow direction assumed when the caller doesn't specify one. */
	static readonly DEFAULT_FLOW = OperationalCostFlow.DEBIT

	static create(data: {
		storeId: string
		category: OperationalCostCategory
		flow?: OperationalCostFlow
		description: string
		amount: { amountCents: number; currency: CurrencyCode }
		recurrency: OperationalCostRecurrency
		startDate: Date
		endDate?: Date
	}): OperationalCost {
		if (data.endDate !== undefined && data.startDate > data.endDate) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'startDate must be <= endDate')
		}
		return new OperationalCost({
			storeId: data.storeId,
			category: data.category,
			flow: data.flow ?? OperationalCost.DEFAULT_FLOW,
			description: data.description,
			amount: data.amount,
			recurrency: data.recurrency,
			startDate: data.startDate,
			endDate: data.endDate ?? null,
			statusOverrides: [],
			deletedAt: null,
		})
	}

	update(patch: {
		category?: OperationalCostCategory
		flow?: OperationalCostFlow
		description?: string
		amount?: { amountCents: number; currency: CurrencyCode }
		recurrency?: OperationalCostRecurrency
		startDate?: Date
		endDate?: Date | null
	}): void {
		if (this.deletedAt !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'cannot update a deleted OperationalCost')
		}
		const effectiveStart = patch.startDate ?? this.startDate
		const effectiveEnd = patch.endDate !== undefined ? patch.endDate : this.endDate
		if (effectiveEnd !== null && effectiveStart > effectiveEnd) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'startDate must be <= endDate')
		}
		if (patch.category !== undefined) {
			this.category = patch.category
		}
		if (patch.flow !== undefined) {
			this.flow = patch.flow
		}
		if (patch.description !== undefined) {
			this.description = patch.description
		}
		if (patch.amount !== undefined) {
			this.amount = new MonetaryAmount(patch.amount)
		}
		if (patch.recurrency !== undefined) {
			this.recurrency = patch.recurrency
		}
		if (patch.startDate !== undefined) {
			this.startDate = patch.startDate
		}
		if (patch.endDate !== undefined) {
			this.endDate = patch.endDate
		}
		this.validate()
	}

	/**
	 * Records (or clears) a per-occurrence status deviation. Setting an
	 * occurrence back to `DEFAULT_OCCURRENCE_STATUS` *drops* its override so
	 * the overrides array stays minimal — the exclusion set never holds rows
	 * that match the default.
	 */
	setStatusOverride(occurrenceDate: Date, status: OperationalCostPaymentStatus): void {
		if (this.deletedAt !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'cannot override status on a deleted OperationalCost')
		}
		const i = this.statusOverrides.findIndex(o => o.occurrenceDate.getTime() === occurrenceDate.getTime())
		if (status === OperationalCost.DEFAULT_OCCURRENCE_STATUS) {
			if (i >= 0) this.statusOverrides.splice(i, 1)
		} else if (i >= 0) {
			this.statusOverrides[i] = { occurrenceDate, status }
		} else {
			this.statusOverrides.push({ occurrenceDate, status })
		}
		this.validate()
	}

	/** End of the occurrence series: explicit `endDate`, or `now` for an open-ended cost. */
	private effectiveEnd(now: Date): Date {
		return this.endDate ?? now
	}

	/** Status for a derived occurrence — the override if one exists, else the default. */
	resolveStatus(occurrenceDate: Date): OperationalCostPaymentStatus {
		return (
			this.statusOverrides.find(o => o.occurrenceDate.getTime() === occurrenceDate.getTime())?.status ??
			OperationalCost.DEFAULT_OCCURRENCE_STATUS
		)
	}

	/**
	 * Strategy 1 — **windowed expansion**. Derives occurrences in `[from, to)`
	 * (bounded by the series) and returns the total count plus only the
	 * requested `page`/`limit` slice, each resolved to its status. At most
	 * `limit` occurrences are materialized regardless of series length.
	 */
	expandOccurrences(input: { from: Date; to: Date; page: number; limit: number; now?: Date }): {
		total: number
		occurrences: OperationalCostOccurrence[]
	} {
		const { total, dates } = occurrenceWindow(
			this.startDate,
			this.effectiveEnd(input.now ?? new Date()),
			this.recurrency,
			input.from,
			input.to,
			input.page,
			input.limit,
		)
		return { total, occurrences: dates.map(occurrenceDate => ({ occurrenceDate, status: this.resolveStatus(occurrenceDate) })) }
	}

	/**
	 * Strategy 2 — **multiplication**. The cost incurred in `[from, to)` is
	 * `(occurrences − cancelled) × amount`: the full derived count, minus the
	 * occurrences excluded by a CANCELLED override. No occurrences are
	 * materialized — counting is O(1) arithmetic. (PAID/UNPAID/OVERDUE are
	 * payment-tracking states; the expense is still incurred, so only
	 * CANCELLED removes it from the total.)
	 */
	incurredCentsBetween(from: Date, to: Date, now?: Date): number {
		const end = this.effectiveEnd(now ?? new Date())
		const count = countOccurrencesInRange(this.startDate, end, this.recurrency, from, to)
		const cancelled = this.statusOverrides.filter(
			o =>
				o.status === OperationalCostPaymentStatus.CANCELLED &&
				o.occurrenceDate.getTime() >= Math.max(from.getTime(), this.startDate.getTime()) &&
				o.occurrenceDate.getTime() < to.getTime() &&
				o.occurrenceDate.getTime() <= end.getTime(),
		).length
		return Math.max(0, count - cancelled) * this.amount.amountCents
	}

	delete(): void {
		if (this.deletedAt !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'OperationalCost already deleted')
		}
		this.deletedAt = new Date()
		this.validate()
	}

	get isDeleted(): boolean {
		return this.deletedAt !== null
	}
}

export interface OperationalCost extends OperationalCostProps {}

import { injectable } from 'tsyringe-neo'
import { Handler, z, type Transaction } from '@bk-dash/core-typescript'

import { MonetaryAmountSchema } from '../../shared/objects'
import { OperationalCost } from '../entities/OperationalCost'
import { OperationalCostRepository } from '../repositories/OperationalCostRepository'
import { OperationalCostCreatedEvent } from '../events'
import { OperationalCostCategory, OperationalCostFlow, OperationalCostRecurrency } from '@bk-dash/contracts-typescript/wire/enums'

export const CreateOperationalCostInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	category: z.enum(OperationalCostCategory),
	flow: z.enum(OperationalCostFlow).default(OperationalCostFlow.DEBIT),
	description: z.string().min(1).max(500),
	amount: MonetaryAmountSchema.refine(m => m.amountCents > 0),
	recurrency: z.enum(OperationalCostRecurrency),
	startDate: z.date(),
	endDate: z.date().optional(),
})

export const CreateOperationalCostOutputSchema = z.object({
	operationalCostId: z.uuid(),
})

/**
 * C41 CreateOperationalCost. Instantiates the aggregate via
 * `OperationalCost.create(...)` (validates the date range), persists,
 * and emits OperationalCostCreatedEvent.
 */
@injectable()
export class CreateOperationalCost extends Handler<typeof CreateOperationalCostInputSchema, typeof CreateOperationalCostOutputSchema> {
	readonly name = 'create_operational_cost' as const
	readonly inputSchema = CreateOperationalCostInputSchema
	readonly outputSchema = CreateOperationalCostOutputSchema

	constructor(private readonly costs: OperationalCostRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const entity = OperationalCost.create({
				storeId: input.storeId,
				category: input.category,
				flow: input.flow,
				description: input.description,
				amount: input.amount,
				recurrency: input.recurrency,
				startDate: input.startDate,
				endDate: input.endDate,
			})
			await this.costs.save(entity, tx)

			await this.domainEventRepository.save(
				new OperationalCostCreatedEvent({
					entityId: entity.id.value,
					ownerId: input.storeId,
					payload: { operationalCost: entity.toJSON() },
				}),
				tx,
			)

			return { operationalCostId: entity.id.value }
		})
	}
}

import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z, type Transaction } from '@bk-dash/core-typescript'

import { MonetaryAmountSchema } from '../../shared/objects'
import { OperationalCostRepository } from '../repositories/OperationalCostRepository'
import { OperationalCostUpdatedEvent } from '../events'
import type { FinanceApplicationErrors } from '../errors'
import { OperationalCostCategory, OperationalCostFlow, OperationalCostRecurrency } from '@bk-dash/contracts-typescript/wire/enums'

export const UpdateOperationalCostInputSchema = z.object({
	userId: z.uuid(),
	ids: z.array(z.uuid()).min(1),
	category: z.enum(OperationalCostCategory).optional(),
	flow: z.enum(OperationalCostFlow).optional(),
	description: z.string().min(1).max(500).optional(),
	amount: MonetaryAmountSchema.refine(m => m.amountCents > 0).optional(),
	recurrency: z.enum(OperationalCostRecurrency).optional(),
	startDate: z.date().optional(),
	endDate: z.date().nullable().optional(),
})

export const UpdateOperationalCostOutputSchema = z.void()

/** C42 UpdateOperationalCost. Patches the aggregate via `entity.update(patch)` which validates dates, then persists + emits OperationalCostUpdatedEvent unconditionally. */
@injectable()
export class UpdateOperationalCost extends Handler<typeof UpdateOperationalCostInputSchema, typeof UpdateOperationalCostOutputSchema> {
	readonly name = 'update_operational_cost' as const
	readonly inputSchema = UpdateOperationalCostInputSchema
	readonly outputSchema = UpdateOperationalCostOutputSchema

	constructor(private readonly costs: OperationalCostRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		await this.withTransaction(tx, async tx => {
			for (const id of input.ids) {
				const entity = await this.costs.findById(id, tx)
				if (!entity) {
					throw new BaseError<FinanceApplicationErrors>('OPERATIONAL_COST_NOT_FOUND')
				}

				entity.update({
					category: input.category,
					flow: input.flow,
					description: input.description,
					amount: input.amount,
					recurrency: input.recurrency,
					startDate: input.startDate,
					endDate: input.endDate,
				})

				await this.costs.save(entity, tx)
				await this.domainEventRepository.save(
					new OperationalCostUpdatedEvent({
						entityId: entity.id.value,
						ownerId: entity.storeId.value,
						payload: { operationalCost: entity.toJSON() },
					}),
					tx,
				)
			}
		})

		return
	}
}

