import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { givenStoreIntegration } from '@test/support/given/integrations'
import { BaseError, DomainEventRepository } from '@bk-dash/core-typescript'
import { CurrencyCode, PaymentStatus } from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmount } from '../../shared/objects'
import { UpdateOrderOverride } from './UpdateOrderOverride'
import { OrderOverrideRepository } from '../repositories/OrderOverrideRepository/OrderOverrideRepository'
import { OrderOverriddenEvent } from '../events'

const STORE_A = testId('store', 'a')
const STORE_B = testId('store', 'b')
const ORDER_A = testId('order', 'a')
const ORDER_B = testId('order', 'b')
// externalId is now derived from the store's integration, not passed in.
const EXT_A = 'shop-a.myshopify.com'
const EXT_B = 'shop-b.myshopify.com'
const USER_1 = testId('user', '1')
const USER_2 = testId('user', '2')

describe('UpdateOrderOverride (C26)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let useCase: UpdateOrderOverride
	let repo: OrderOverrideRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		useCase = testBed.resolve(UpdateOrderOverride)
		repo = testBed.resolve(OrderOverrideRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
		// STORE_A is integrated with EXT_A — the override pin externalId is
		// derived from this row, not from the request.
		await givenStoreIntegration(testBed, { storeId: STORE_A, ownerId: 'integration-tenant', externalId: EXT_A })
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readOverriddenEvents() {
		return testBed.resolve(DomainEventRepository).findByType(OrderOverriddenEvent)
	}

	it('creates a fresh override on first call + emits with all fields as changed', async () => {
		const out = await useCase.execute({
			userId: USER_1,
			storeId: STORE_A,
			orderIds: [ORDER_A],
			patch: {
				paymentStatus: PaymentStatus.PAID,
				revenue: new MonetaryAmount({ amountCents: 10_000, currency: CurrencyCode.USD }),
			},
		})

		expect(out.orderOverrideIds).toHaveLength(1)
		expect(out.orderOverrideIds[0]).toMatch(/^[0-9a-f-]{36}$/)

		const saved = await repo.findByPin(ORDER_A, EXT_A)
		expect(saved?.fields.paymentStatus).toBe(PaymentStatus.PAID)
		expect(saved?.fields.revenue).toEqual(new MonetaryAmount({ amountCents: 10_000, currency: CurrencyCode.USD }))

		const emitted = await readOverriddenEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.orderId).toBe(ORDER_A)
		expect(emitted[0]!.payload.storeIntegrationExternalId).toBe(EXT_A)
		expect(emitted[0]!.payload.entity.fields.paymentStatus).toBe(PaymentStatus.PAID)
		expect(emitted[0]!.payload.entity.fields.revenue).toEqual({ amountCents: 10_000, currency: CurrencyCode.USD })
	})

	it('merges patch into existing override + emits only the changed keys', async () => {
		// first call: set paymentStatus + revenue
		await useCase.execute({
			userId: USER_1,
			storeId: STORE_A,
			orderIds: [ORDER_A],
			patch: {
				paymentStatus: PaymentStatus.PAID,
				revenue: new MonetaryAmount({ amountCents: 10_000, currency: CurrencyCode.USD }),
			},
		})

		// second call by a different user: change paymentStatus + add fees (revenue unchanged)
		await useCase.execute({
			userId: USER_2,
			storeId: STORE_A,
			orderIds: [ORDER_A],
			patch: {
				paymentStatus: PaymentStatus.REFUNDED,
				fees: new MonetaryAmount({ amountCents: 250, currency: CurrencyCode.USD }),
			},
		})

		const saved = await repo.findByPin(ORDER_A, EXT_A)
		// revenue preserved, paymentStatus updated, fees added
		expect(saved?.fields.revenue).toEqual(new MonetaryAmount({ amountCents: 10_000, currency: CurrencyCode.USD }))
		expect(saved?.fields.paymentStatus).toBe(PaymentStatus.REFUNDED)
		expect(saved?.fields.fees).toEqual(new MonetaryAmount({ amountCents: 250, currency: CurrencyCode.USD }))

		const emitted = await readOverriddenEvents()
		expect(emitted).toHaveLength(2)
		expect(emitted[1]!.payload.entity.fields.paymentStatus).toBe(PaymentStatus.REFUNDED)
		expect(emitted[1]!.payload.entity.fields.fees).toEqual({ amountCents: 250, currency: CurrencyCode.USD })
	})

	it('is a no-op + emits no event when the patch matches existing fields', async () => {
		await useCase.execute({
			userId: USER_1,
			storeId: STORE_A,
			orderIds: [ORDER_A],
			patch: { paymentStatus: PaymentStatus.PAID },
		})

		const beforeId = (await repo.findByPin(ORDER_A, EXT_A))!.id.value

		const out = await useCase.execute({
			userId: USER_2,
			storeId: STORE_A,
			orderIds: [ORDER_A],
			patch: { paymentStatus: PaymentStatus.PAID }, // same value
		})

		expect(out.orderOverrideIds).toHaveLength(1)
		expect(out.orderOverrideIds[0]).toBe(beforeId)
		const saved = await repo.findByPin(ORDER_A, EXT_A)
		// fields unchanged — paymentStatus still PAID from the first call.
		expect(saved?.fields.paymentStatus).toBe(PaymentStatus.PAID)

		const emitted = await readOverriddenEvents()
		expect(emitted).toHaveLength(1) // only the first create's event
	})

	it('batch-applies the patch across all orderIds in one call', async () => {
		const out = await useCase.execute({
			userId: USER_1,
			storeId: STORE_A,
			orderIds: [ORDER_A, ORDER_B],
			patch: { paymentStatus: PaymentStatus.PENDING },
		})

		expect(out.orderOverrideIds).toHaveLength(2)
		expect((await repo.findByPin(ORDER_A, EXT_A))?.fields.paymentStatus).toBe(PaymentStatus.PENDING)
		expect((await repo.findByPin(ORDER_B, EXT_A))?.fields.paymentStatus).toBe(PaymentStatus.PENDING)

		const emitted = await readOverriddenEvents()
		expect(emitted).toHaveLength(2)
	})

	it('derives the override pin externalId from each store’s own integration', async () => {
		// STORE_B integrated with a different shop — its override pins on EXT_B.
		await givenStoreIntegration(testBed, { storeId: STORE_B, ownerId: 'integration-tenant', externalId: EXT_B })

		await useCase.execute({
			userId: USER_1,
			storeId: STORE_A,
			orderIds: [ORDER_A],
			patch: { paymentStatus: PaymentStatus.PAID },
		})
		await useCase.execute({
			userId: USER_1,
			storeId: STORE_B,
			orderIds: [ORDER_A],
			patch: { paymentStatus: PaymentStatus.REFUNDED },
		})

		const oa = await repo.findByPin(ORDER_A, EXT_A)
		const ob = await repo.findByPin(ORDER_A, EXT_B)
		expect(oa?.fields.paymentStatus).toBe(PaymentStatus.PAID)
		expect(ob?.fields.paymentStatus).toBe(PaymentStatus.REFUNDED)
		expect(oa?.id.value).not.toBe(ob?.id.value)

		const emitted = await readOverriddenEvents()
		expect(emitted).toHaveLength(2)
	})

	it('throws STORE_INTEGRATION_NOT_FOUND when the store has no integration', async () => {
		await expect(
			useCase.execute({
				userId: USER_1,
				storeId: STORE_B, // no integration set up for STORE_B
				orderIds: [ORDER_A],
				patch: { paymentStatus: PaymentStatus.PAID },
			}),
		).rejects.toThrow(BaseError)
	})
})

import { BaseValueObject, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { QuantityModifier } from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmount } from '../../shared/objects'

export const ProductCostOptionItemSchema = z.object({
	id: z.instance(Id),
	variantIds: z.array(z.instance(Id)).min(1),
	quantity: z.number().int().positive(),
	quantityModifier: z.enum(QuantityModifier),
	unitCost: z.instance(MonetaryAmount),
	/** SHA-1 of sorted variantIds — used for overlap detection. Computed by the aggregate, not supplied by the caller. */
	variantsHash: z.string(),
})

export type ProductCostOptionItemProps = Z.infer<typeof ProductCostOptionItemSchema>

/**
 * One per-variant × qty-tier cost line inside a {@link ProductCostOption}.
 * A composite value object: no independent lifecycle — it is materialized
 * and serialized inline within the `ProductCost` aggregate's JSON column.
 */
export class ProductCostOptionItem extends BaseValueObject<typeof ProductCostOptionItemSchema> {
	static override schema = ProductCostOptionItemSchema
}

export interface ProductCostOptionItem extends ProductCostOptionItemProps {}

import Z from 'zod'
import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import { ProductCostType, CurrencyCode, Country } from '@bk-dash/contracts-typescript/wire/enums'
import { Timeline } from '../../shared/objects'
import { ProductCostOption, ProductCostOptionSchema } from '../objects/ProductCostOption'
import { ProductCostOptionItem, ProductCostOptionItemSchema } from '../objects/ProductCostOptionItem'
import type { CatalogApplicationErrors } from '../errors'

// `ProductCostOption` / `ProductCostOptionItem` are aggregate-internal value
// objects (live in `../objects`). Re-exported so existing importers keep their
// `../entities/ProductCost` path.
export { ProductCostOption, ProductCostOptionSchema, ProductCostOptionItem, ProductCostOptionItemSchema }

export const ProductCostSchema = z.object({
	storeId: z.instance(Id),
	storeIntegrationId: z.instance(Id),
	/** Null when scoped to a kit (multi-variant bundle priced together). */
	productId: z.instance(Id).nullable(),
	costType: z.enum(ProductCostType),
	options: z.array(z.instance(ProductCostOption)),
	deletedAt: z.date().nullable(),
})

export type ProductCostProps = Z.infer<typeof ProductCostSchema>

// ─── Input schemas (no computed fields, used by use cases / controllers) ──────

// Derived from ProductCostOptionItemSchema: strips computed `id` + `variantsHash`,
// unwraps z.instance(Id) → string and z.instance(MonetaryAmount) → { amountCents, currency }.
// No casts needed — .input() returns a properly typed ZodObject; .omit() chains directly.
export const ProductCostOptionItemInputSchema = ProductCostOptionItemSchema.input().omit({ id: true, variantsHash: true })

export const ProductCostOptionInputSchema = z.object({
	currency: z.enum(CurrencyCode),
	country: z.enum(Country).optional(),
	startDate: z.iso.date(),
	endDate: z.iso.date().optional(),
	items: z.array(ProductCostOptionItemInputSchema).min(1),
})

export type ProductCostOptionInput = Z.infer<typeof ProductCostOptionInputSchema>

/**
 * Deterministic hash of a sorted variant-ID set.
 * In production this should use crypto.createHash; for the Mock layer a
 * stable string sort + join is sufficient and produces consistent overlap
 * detection without the crypto dep at this module's load time.
 */
function hashVariantIds(variantIds: string[]): string {
	return [...variantIds].sort().join('|')
}

function buildItems(items: ProductCostOptionInput['items']) {
	return items.map(item => ({
		id: crypto.randomUUID(),
		variantIds: item.variantIds,
		quantity: item.quantity,
		quantityModifier: item.quantityModifier,
		unitCost: item.unitCost,
		variantsHash: hashVariantIds(item.variantIds),
	}))
}

interface PaintedOptionValue {
	items: ReturnType<typeof buildItems>
	startDate: Date
	endDate: Date | null
}
interface PaintedOption {
	id: string
	currency: CurrencyCode
	country?: Country
	values: PaintedOptionValue[]
}

/** Group input options by (currency, country); paint each value onto that key's Timeline. */
function groupAndPaint(inputs: ProductCostOptionInput[]): PaintedOption[] {
	const byKey = new Map<string, PaintedOption>()
	for (const opt of inputs) {
		const key = `${opt.currency}|${opt.country ?? ''}`
		const value: PaintedOptionValue = {
			items: buildItems(opt.items),
			startDate: new Date(opt.startDate),
			endDate: opt.endDate ? new Date(opt.endDate) : null,
		}
		const entry = byKey.get(key)
		if (entry) entry.values = [...new Timeline(entry.values).place(value).entries]
		else byKey.set(key, { id: crypto.randomUUID(), currency: opt.currency, country: opt.country, values: [value] })
	}
	return [...byKey.values()]
}

/**
 * `ProductCost` aggregate per spec § 4 BC5.
 *
 * One `ProductCost` represents a merchant's cost configuration for a
 * (storeIntegration × product?) scope. It holds one or more
 * `ProductCostOption`s — each scoped by currency and country — which in turn
 * hold a `values` Timeline of `{ items }` (the per-variant unit costs that
 * change over time).
 *
 * - Invariant: each option's `values` timeline is non-overlapping
 *   (Timeline-enforced); at most one option per (currency, country).
 * - Soft-delete: `deletedAt` is set by `delete()`; the row is preserved for
 *   historical COGS attribution.
 * - Scoping keys (storeIntegrationId, productId) are immutable after creation.
 */
export class ProductCost extends AggregateRoot<typeof ProductCostSchema> {
	static override schema = ProductCostSchema

	static create(data: {
		storeId: string
		storeIntegrationId: string
		productId: string | null
		costType: ProductCostType
		options: ProductCostOptionInput[]
	}): ProductCost {
		// Group by (currency, country) and paint each value onto the option's Timeline.
		// Then validate each painted option through ProductCostOptionSchema.
		const options = groupAndPaint(data.options)

		for (const opt of options) {
			const r = ProductCostOptionSchema.safeParse(opt)
			if (!r.success) throw new BaseError(r.error.issues[0]!.message)
		}

		return new ProductCost({
			id: crypto.randomUUID(),
			storeId: data.storeId,
			storeIntegrationId: data.storeIntegrationId,
			productId: data.productId,
			costType: data.costType,
			options,
			deletedAt: null,
		})
	}

	/** Updates mutable fields — the full options set. */
	update(data: { options?: ProductCostOptionInput[] }): void {
		if (this.deletedAt !== null) {
			throw new BaseError<CatalogApplicationErrors>('PRODUCT_COST_NOT_FOUND')
		}
		if (data.options !== undefined) {
			const options = groupAndPaint(data.options)
			for (const opt of options) {
				const r = ProductCostOptionSchema.safeParse(opt)
				if (!r.success) throw new BaseError(r.error.issues[0]!.message)
			}
			// Materialize the plain options into ProductCostOption value objects
			// through the aggregate's own field schema — no `new` in the body.
			this.options = ProductCostSchema.shape.options.parse(options)
		}
		this.validate()
	}

	/** Soft-delete. Preserved for historical COGS attribution. */
	delete(): void {
		if (this.deletedAt !== null) {
			throw new BaseError<CatalogApplicationErrors>('PRODUCT_COST_NOT_FOUND')
		}
		this.deletedAt = new Date()
		this.validate()
	}

	get isDeleted(): boolean {
		return this.deletedAt !== null
	}
}

export interface ProductCost extends ProductCostProps {}

import { describe, it, expect } from 'bun:test'
import { BaseError } from '@bk-dash/core-typescript'
import { CurrencyCode, Country, ProductCostType, QuantityModifier } from '@bk-dash/contracts-typescript/wire/enums'
import { ProductCost, type ProductCostOptionInput } from './ProductCost'

const VARIANT = '11111111-1111-4111-8111-111111111111'
const items = [
	{ variantIds: [VARIANT], quantity: 1, quantityModifier: QuantityModifier.EQ, unitCost: { amountCents: 500, currency: CurrencyCode.USD } },
]
const opt = (startDate: string, endDate?: string): ProductCostOptionInput => ({
	currency: CurrencyCode.USD,
	country: Country.US,
	startDate,
	endDate,
	items,
})
const create = (options: ProductCostOptionInput[]) =>
	ProductCost.create({
		storeId: '22222222-2222-4222-8222-222222222222',
		storeIntegrationId: '33333333-3333-4333-8333-333333333333',
		productId: '44444444-4444-4444-8444-444444444444',
		costType: ProductCostType.SINGLE,
		options,
	})
const usOption = (pc: ProductCost) => pc.options.find(o => o.currency === CurrencyCode.USD && o.country === Country.US)

describe('ProductCost', () => {
	it('creates one option per (currency,country) with a values timeline', () => {
		const pc = create([opt('2026-05-01')])
		expect(pc.options).toHaveLength(1)
		expect(usOption(pc)!.values).toHaveLength(1)
		expect(usOption(pc)!.values[0]!.endDate).toBeNull()
	})

	it('two values for the same (currency,country) supersede into one option, not two', () => {
		const pc = create([opt('2026-05-01'), opt('2026-09-01')])
		expect(pc.options).toHaveLength(1) // single (USD,US) option
		const values = usOption(pc)!.values
		expect(values).toHaveLength(2) // [.., 2026-09-01) + [2026-09-01, ∞)
		expect(values.find(v => v.endDate === null)).toBeDefined()
	})

	it('rejects a zero-length value window (startDate === endDate)', () => {
		expect(() => create([opt('2026-05-01', '2026-05-01')])).toThrow(BaseError)
	})
})

