import { BaseValueObject } from '@bk-dash/core-typescript'
import { z } from '@bk-dash/core-typescript'

import Z from 'zod'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'

export const MoneySchema = z.object({
	amountCents: z.number().int().nonnegative(),
	currency: z.enum(CurrencyCode),
})

/**
 * Signed variant for computed reporting figures (gross margin, profit, …) that
 * can legitimately be negative. NOT a stored Money value object — it's the
 * read-side shape for analytics outputs, so it drops the `.nonnegative()`.
 */
export const SignedMoneySchema = z.object({
	amountCents: z.number().int(),
	currency: z.enum(CurrencyCode),
})

export class Money extends BaseValueObject<typeof MoneySchema> {
	static override schema = MoneySchema

	equals(other: Money): boolean {
		return this.amountCents === other.amountCents && this.currency === other.currency
	}
}

export interface Money extends Z.infer<typeof MoneySchema> {}

import { PrimitiveValueObject } from './ValueObject'
import { BaseError } from '../types/BaseError'
import type { BaseDomainErrors } from '../errors/codes'
import type { z, ZodString, ZodType } from 'zod'

export abstract class BasePrimitiveValueObject<T extends ZodType = ZodString> extends PrimitiveValueObject<z.output<T>> {
	static schema?: ZodType
	declare readonly value: z.output<T>

	static transformed() {
		// biome-ignore lint/complexity/noThisInStatic: polymorphic this pattern — subclasses call BasePrimitiveValueObject.transformed() and `this` must resolve to the subclass constructor at runtime
		const Cls = this as unknown as { schema: ZodType; new (props: unknown): BasePrimitiveValueObject }
		return Cls.schema.transform((v: unknown) => new Cls(v))
	}

	constructor(value: z.input<T>) {
		super()
		const schema = (this.constructor as typeof BasePrimitiveValueObject).schema
		const result = schema?.safeParse(value)

		if (result && !result.success) {
			throw new BaseError<BaseDomainErrors>(result.error.issues[0]!.message as BaseDomainErrors)
		}

		Object.assign(this, { value: result?.data ?? value })
	}
}

import { z, type ZodObject, type ZodRawShape, type ZodTypeAny, type ZodLiteral, ZodDiscriminatedUnion } from 'zod'
import { instanceInputSchemaMap } from './InstanceRegistry'
import { stringToInteger } from './Transforms'

/**
 * Branded return type of `z.instance()`. Carries the VO schema type `S` as a
 * phantom field so that the `.input()` type mapper can recover the wire-input
 * shape at the type level — without changing any runtime behaviour.
 *
 * `ZodInstance<S, T>` extends `z.ZodType<T, T | z.input<S>>`, so it is
 * assignable everywhere a `ZodType` is expected.
 */
export interface ZodInstance<S extends ZodTypeAny, T> extends z.ZodType<T, T | z.input<S>> {
	/** Phantom — never set at runtime; lets `.input()` recover the VO schema type. */
	readonly _voSchema?: S
}
import { BaseEventSchema } from '../../types/BaseEvent'
import { BaseDomainEventSchema } from '../../types/BaseDomainEvent'
import { BaseIntegrationEventSchema } from '../../types/BaseIntegrationEvent'

// Meta options with examples
interface SchemaOptions {
	examples?: unknown[]
}

type IntegrationEventObjectSchema<T extends ZodRawShape> = ZodObject<
	Omit<(typeof BaseIntegrationEventSchema)['shape'], 'payload' | 'name'> & { name: ZodLiteral<string>; payload: ZodObject<T> }
>

type IntegrationEventWithPayloadSchema<T extends ZodTypeAny> = ZodObject<
	Omit<(typeof BaseIntegrationEventSchema)['shape'], 'payload' | 'name'> & { name: ZodLiteral<string>; payload: T }
>

type DomainEventObjectSchema<T extends ZodRawShape> = ZodObject<
	Omit<(typeof BaseDomainEventSchema)['shape'], 'payload'> & { payload: ZodObject<T> }
>

type DomainEventWithPayloadSchema<T extends ZodTypeAny> = ZodObject<
	Omit<(typeof BaseDomainEventSchema)['shape'], 'payload'> & { payload: T }
>

type BaseEventObjectSchema<T extends ZodRawShape> = ZodObject<
	Omit<(typeof BaseEventSchema)['shape'], 'payload'> & { payload: ZodObject<T> }
>

// Helper to get examples from schema meta
const getExamples = (schema: ZodTypeAny): unknown[] => {
	// Access meta from the schema definition - Zod v4 uses 'def' property
	const def = (schema as unknown as { def?: { meta?: SchemaOptions } }).def
	return def?.meta?.examples ?? []
}

// Helper function to merge examples from two schemas
const mergeExamples = (baseExamples: unknown[] = [], additionalExamples: unknown[] = []) => {
	if (baseExamples.length === 0) return additionalExamples
	if (additionalExamples.length === 0) return baseExamples

	const merged: unknown[] = []

	// Create all possible combinations
	for (const baseExample of baseExamples) {
		for (const additionalExample of additionalExamples) {
			merged.push({
				...(baseExample as object),
				...(additionalExample as object),
			})
		}
	}

	return merged
}

// PaginatedQuery schema
export const PaginatedQuery = z
	.object({
		page: stringToInteger({ minimum: 1 }).default(1),
		limit: stringToInteger({ minimum: 1, maximum: 100 }).default(10),
		search: z.string().optional(),
	})
	.meta({
		examples: [
			{
				limit: 10,
				page: 1,
				search: 'Kitten drinking coffee.',
			},
		],
	})

/**
 * Builds a paginated query schema with additional properties
 */
export function paginatedQuery(properties?: undefined, options?: SchemaOptions): typeof PaginatedQuery
export function paginatedQuery<T extends ZodRawShape>(
	properties: T,
	options?: SchemaOptions,
): ZodObject<(typeof PaginatedQuery)['shape'] & T>
export function paginatedQuery<T extends ZodRawShape>(properties?: T, options?: SchemaOptions) {
	if (!properties) return PaginatedQuery

	const baseExamples = getExamples(PaginatedQuery)
	const mergedExamples = mergeExamples(baseExamples, options?.examples)

	return z
		.object({
			...PaginatedQuery.shape,
			...properties,
		})
		.meta({ examples: mergedExamples })
}

// PaginatedData base schema
export const PaginatedData = z
	.object({
		items: z.array(z.unknown()),
		total: z.number(),
		totalPages: z.number(),
	})
	.meta({ examples: [] })

/**
 * Builds a paginated response schema with typed items
 */
export function paginatedResponse<T extends ZodRawShape>(
	properties: T,
	options?: SchemaOptions,
): ZodObject<{
	items: z.ZodArray<ZodObject<T>>
	total: z.ZodNumber
	totalPages: z.ZodNumber
}> {
	const baseExamples = getExamples(PaginatedData)
	const mergedExamples = mergeExamples(baseExamples, options?.examples)

	const itemSchema = z.object(properties)
	const itemsArraySchema = z.array(itemSchema)

	return z
		.object({
			items: itemsArraySchema,
			total: z.number(),
			totalPages: z.number(),
		})
		.meta({ examples: mergedExamples }) as any
}

/**
 * Builds a base event schema with custom payload properties
 */
export function baseEvent(properties?: undefined, options?: SchemaOptions): typeof BaseEventSchema
export function baseEvent<T extends ZodRawShape>(properties: T, options?: SchemaOptions): BaseEventObjectSchema<T>
export function baseEvent<T extends ZodRawShape>(properties?: T, options?: SchemaOptions) {
	if (!properties) return BaseEventSchema.meta({ examples: options?.examples ?? [] })

	const payloadSchema = z.object(properties)
	const mergedExamples = options?.examples ?? []

	const { payload: _payload, ...baseShape } = BaseEventSchema.shape

	return z
		.object({
			...baseShape,
			payload: payloadSchema,
		})
		.meta({ examples: mergedExamples })
}

/**
 * Builds a domain event schema with custom payload properties
 */
export function domainEvent(properties?: undefined, options?: SchemaOptions): typeof BaseDomainEventSchema
export function domainEvent<T extends ZodTypeAny>(schema: T, options?: SchemaOptions): DomainEventWithPayloadSchema<T>
export function domainEvent<T extends ZodRawShape>(properties: T, options?: SchemaOptions): DomainEventObjectSchema<T>
export function domainEvent(properties?: ZodRawShape | ZodTypeAny, options?: SchemaOptions) {
	if (!properties) return BaseDomainEventSchema.meta({ examples: options?.examples ?? [] })

	const mergedExamples = options?.examples ?? []
	const { payload: _payload, ...baseShape } = BaseDomainEventSchema.shape

	const payloadSchema = '_zod' in properties ? properties : z.object(properties as ZodRawShape)

	return z
		.object({
			...baseShape,
			payload: payloadSchema,
		})
		.meta({ examples: mergedExamples })
}
/**
 * Builds an integration event schema with a baked-in z.literal name for discriminatedUnion support.
 */
export function integrationEvent(
	name: string,
	options?: SchemaOptions,
): ZodObject<{
	name: ZodLiteral<string>
	payload: (typeof BaseIntegrationEventSchema)['shape']['payload']
	ownerId: (typeof BaseIntegrationEventSchema)['shape']['ownerId']
}>
export function integrationEvent<T extends ZodTypeAny>(
	name: string,
	schema: T,
	options?: SchemaOptions,
): IntegrationEventWithPayloadSchema<T>
export function integrationEvent<T extends ZodRawShape>(
	name: string,
	properties: T,
	options?: SchemaOptions,
): IntegrationEventObjectSchema<T>
export function integrationEvent(name: string, properties?: ZodRawShape | ZodTypeAny | SchemaOptions, options?: SchemaOptions) {
	// Allow (name) / (name, options) / (name, schema) / (name, schema, options) / (name, properties, options).
	let resolvedProperties: ZodRawShape | ZodTypeAny | undefined
	let resolvedOptions: SchemaOptions | undefined

	if (properties && typeof properties === 'object' && !('_zod' in properties) && !Array.isArray(properties)) {
		// Either ZodRawShape or SchemaOptions (which has only `examples`).
		const keys = Object.keys(properties)
		const looksLikeOptions = keys.length === 1 && keys[0] === 'examples'
		if (looksLikeOptions) {
			resolvedOptions = properties as SchemaOptions
		} else {
			resolvedProperties = properties as ZodRawShape
			resolvedOptions = options
		}
	} else if (properties && '_zod' in (properties as object)) {
		resolvedProperties = properties as ZodTypeAny
		resolvedOptions = options
	} else {
		resolvedOptions = options
	}

	const mergedExamples = resolvedOptions?.examples ?? []
	const { name: _name, payload: _payload, ...baseShape } = BaseIntegrationEventSchema.shape

	if (resolvedProperties === undefined) {
		return z
			.object({ ...baseShape, name: z.literal(name), payload: BaseIntegrationEventSchema.shape.payload })
			.meta({ examples: mergedExamples })
	}

	const payloadSchema =
		'_zod' in (resolvedProperties as object) ? (resolvedProperties as ZodTypeAny) : z.object(resolvedProperties as ZodRawShape)

	return z.object({ ...baseShape, name: z.literal(name), payload: payloadSchema }).meta({ examples: mergedExamples })
}

// Time-effective window appended to any schema by `z.historical`. `endDate`
// null = open-ended / currently active. `z.coerce.date()` lets jsonb-stored
// ISO strings rehydrate to Date on read without manual parsing.
const TimeWindowShape = {
	startDate: z.coerce.date(),
	endDate: z.coerce.date().nullable().default(null),
}

// Cast to the broader refine callback type Zod v4 expects internally.
const windowIsValid = (w: unknown) => {
	const win = w as { startDate: Date; endDate: Date | null }
	return win.endDate === null || win.startDate < win.endDate
}
const INVALID_RANGE = { error: 'INVALID_DATE_RANGE' } as const

/**
 * Extends a schema with a validated `[startDate, endDate)` window.
 * Accepts a raw shape, a ZodObject, or a discriminated union (window
 * applied per-variant so the discriminator stays narrowable).
 *
 * `endDate` is nullable with a default of `null` (open-ended / currently active).
 * `z.coerce.date()` lets jsonb-stored ISO strings rehydrate to Date on read.
 * A `startDate < endDate` refine emits `INVALID_DATE_RANGE` on violation.
 */
export function historical<T extends ZodRawShape>(shape: T): ZodObject<T & typeof TimeWindowShape>
export function historical<T extends ZodTypeAny>(schema: T): z.ZodType<z.output<T> & { startDate: Date; endDate: Date | null }>
export function historical(input: ZodRawShape | ZodTypeAny): ZodTypeAny {
	if (!('_zod' in (input as object))) {
		// Raw shape — wrap in ZodObject then extend + refine
		return (z.object(input as ZodRawShape) as ZodObject<ZodRawShape>)
			.extend(TimeWindowShape)
			.refine(windowIsValid, INVALID_RANGE) as unknown as ZodTypeAny
	}
	const schema = input as ZodTypeAny
	// Discriminated union — extend each variant so the discriminator stays narrowable.
	// Zod v4: def.type is 'union' for discriminated unions; use instanceof instead.
	if (schema instanceof ZodDiscriminatedUnion) {
		// Access def via unknown cast — Zod v4 generics are complex; we only need
		// the discriminator string and the options array of ZodObjects at runtime.
		const du = schema as unknown as { def: { discriminator: string; options: ZodObject<ZodRawShape>[] } }
		const widened = du.def.options.map(o => o.extend(TimeWindowShape))
		return (z.discriminatedUnion(du.def.discriminator, widened as never) as ZodTypeAny).refine(windowIsValid, INVALID_RANGE)
	}
	// Plain ZodObject or any other schema — extend + refine
	return (schema as ZodObject<ZodRawShape>).extend(TimeWindowShape).refine(windowIsValid, INVALID_RANGE)
}

/**
 * Creates a schema that parses input and transforms it into a class instance.
 * The class must have a static `schema` property (BaseValueObject, BasePrimitiveValueObject, or BaseEntity).
 *
 * @example
 * ```ts
 * crm: z.instance(CRM),
 * userId: z.instance(Id),
 * specialties: z.array(z.instance(DoctorSpecialty)).default([]),
 * ```
 */
function instance<S extends ZodTypeAny, T>(Cls: { schema: S; new (props: any): T }): ZodInstance<S, T> {
	// Accept already-constructed instances (idempotent for re-validation via
	// this.validate()) OR raw input (the constructor validates via static
	// schema). The declared input type mirrors both runtime branches so
	// call sites can pass either an instance or a props object without casts.
	const schema = z.unknown().transform((v: any) => (v instanceof Cls ? v : new Cls(v))) as unknown as ZodInstance<S, T>
	// Register the underlying VO schema so that .input() can recover it instead
	// of returning z.unknown(). This does NOT change parse-time behaviour.
	instanceInputSchemaMap.set(schema as z.ZodTypeAny, Cls.schema as z.ZodTypeAny)
	return schema
}

/**
 * Like `z.record(z.enum(E), value)` but emits EXPLICIT per-member properties, so
 * the generated OpenAPI/SDK is keyed by the enum members (`{ marketing: V, … }`)
 * instead of a string-indexed map (`{ [k: string]: V }`). All members are
 * required — segments always carry every key (0/empty when there's no data).
 *
 * The OpenAPI generator also emits E as a named enum component (so the SDK carries
 * an iterable enum const) by matching the property-key set against the registered
 * enums — see `OpenAPI.processSchemaForEnums`. So an enum used ONLY via `enumRecord`
 * is still exported, exactly as a `z.enum()` field would be.
 *
 * @example
 * ```ts
 * segments: z.enumRecord(CostKind, MetricSchema),        // { marketing: Metric, … }
 * byStatus: z.enumRecord(PaymentStatus, TallySchema),
 * ```
 */
function enumRecord<T extends Record<string, string>, V extends ZodTypeAny>(
	enumObject: T,
	valueSchema: V,
): ZodObject<Record<T[keyof T], V>> {
	const shape = {} as Record<T[keyof T], V>
	for (const key of Object.values(enumObject) as T[keyof T][]) shape[key] = valueSchema
	return z.object(shape) as unknown as ZodObject<Record<T[keyof T], V>>
}

// Export all extra schema types with camelCase naming to match Zod convention
export const ExtraSchemaTypes = {
	paginatedQuery,
	paginatedResponse,
	baseEvent,
	domainEvent,
	integrationEvent,
	instance,
	historical,
	enumRecord,
}

/**
 * Generic, domain-agnostic KPI atoms shared across BFF query use cases.
 * Context-specific shapes (Stat, breakdowns, dashboard details, …) live in the
 * owning context's `schemas/` folder, NOT here.
 */
import { z } from '@bk-dash/core-typescript'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'

/** Partial record of ISO-4217 currency → raw numeric value (not cents). A store
 *  reports only the currencies it transacts in, not the full ISO set. */
export const CurrencyAmountSchema = z.partialRecord(z.enum(CurrencyCode), z.number())

/** KPI atom: current value + period-over-period delta fraction (null = no prior period). */
export const MetricSchema = z.object({
	value: z.number(),
	deltaPct: z.number().nullable(),
})

/** Multi-currency Metric (consolidated aggregates that cross currencies). */
export const CurrencyMetricSchema = z.object({
	value: CurrencyAmountSchema,
	deltaPct: z.number().nullable(),
})

/** Generic count + monetary-value atom, each with its own delta. */
export const TallySchema = z.object({
	count: MetricSchema,
	value: MetricSchema,
})

/** Consolidated multi-currency variant: value is a CurrencyMetric. */
export const ConsolidatedTallySchema = z.object({
	count: MetricSchema,
	value: CurrencyMetricSchema,
})

/** Decomposition helper: `{ total, segments: { [enumMember]: Metric } }` (enum-keyed). */
export function segmented<T extends Record<string, string>>(enumObject: T) {
	return z.object({
		total: MetricSchema,
		segments: z.enumRecord(enumObject, MetricSchema),
	})
}

// Deterministic faker helpers for mocked BFF controllers. A fixed seed makes
// every server boot produce the same fixtures, so SDK output and frontend
// snapshots stay stable. Swap a usecase's body for a real query and delete the
// faker calls — nothing else changes.
import { faker } from '@faker-js/faker'

faker.seed(1)

export { faker }

export const mockId = (): string => faker.string.uuid()

/** Raw monetary value (not cents) in the display currency. */
export const mockMoney = (): number => faker.number.float({ min: 0, max: 100_000, fractionDigits: 2 })

/** A KPI Metric: value + period-over-period delta fraction (-1..1, sometimes null). */
export const mockMetric = (): { value: number; deltaPct: number | null } => ({
	value: faker.number.float({ min: 0, max: 100_000, fractionDigits: 2 }),
	deltaPct: faker.datatype.boolean() ? faker.number.float({ min: -1, max: 1, fractionDigits: 2 }) : null,
})

export const mockSeries = <T>(n: number, fn: (index: number) => T): T[] => Array.from({ length: n }, (_, i) => fn(i))

/** Recent ISO-8601 timestamp. */
export const mockIsoDate = (): string => faker.date.recent({ days: 30 }).toISOString()

export const pick = <T>(values: readonly T[]): T => faker.helpers.arrayElement(values)

import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'
import { TenancyScope, PixelEventType } from '@bk-dash/contracts-typescript/wire/enums'
import { MetricSchema, TallySchema } from '../../shared/schemas'
import { faker, mockMetric } from '../../shared/testing/mock'

// ---------------------------------------------------------------------------
// Input — `tenancyScope` is input-only (selects the store set; output shape is
// identical). storeId/storeIds from ctx; productIds optional filter.
// ---------------------------------------------------------------------------
export const GetPixelFunnelInputSchema = z.object({
	tenancyScope: z.enum(TenancyScope),
	storeId: z.uuid(), // ← ctx.session.storeId      (SINGLE_STORE)
	storeIds: z.array(z.uuid()), // ← ctx.membership.storeIds  (MULTI_STORE)
	startDate: z.date(),
	endDate: z.date(),
	productIds: z.array(z.uuid()).optional(),
})

// ---------------------------------------------------------------------------
// Output — single flat funnel (summed across the selected stores). Pure counts.
// steps = unique sessions per stage (Metric); rate derived FE (value / base).
// carts = abandoned carts Tally (count + lost value).
// ---------------------------------------------------------------------------
export const GetPixelFunnelOutputSchema = z.object({
	hasPixel: z.boolean(),
	base: MetricSchema,
	steps: z.enumRecord(PixelEventType, MetricSchema),
	conversionRate: MetricSchema,
	carts: TallySchema,
})

const recordOf = <T extends Record<string, string>, V>(enumObject: T, fn: () => V): Record<T[keyof T], V> =>
	Object.fromEntries(Object.values(enumObject).map(v => [v, fn()])) as Record<T[keyof T], V>

const seedFrom = (parts: string[]): number => {
	const s = parts.join('|')
	let h = 0
	for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0
	return Math.abs(h) || 1
}

/**
 * `GetPixelFunnel` — pixel funnel for the dashboard FunnelSection.
 *
 * FAKER body, REAL contract. `tenancyScope` selects the store set to query
 * (SINGLE = session store, MULTI = membership stores), summed into one funnel.
 * Real swap: two `PixelEventReadRepository.aggregateFunnelStages(...)` calls
 * (current + prior period) behind this same interface.
 */
@injectable()
export class GetPixelFunnel extends Handler<typeof GetPixelFunnelInputSchema, typeof GetPixelFunnelOutputSchema> {
	readonly name = 'get_pixel_funnel' as const
	readonly inputSchema = GetPixelFunnelInputSchema
	readonly outputSchema = GetPixelFunnelOutputSchema

	protected async handle(input: this['input']): Promise<this['output']> {
		const storeIds = input.tenancyScope === TenancyScope.MULTI_STORE ? input.storeIds : [input.storeId]
		faker.seed(seedFrom([...storeIds, input.startDate.toISOString(), input.endDate.toISOString(), ...(input.productIds ?? [])]))

		return {
			hasPixel: true,
			base: mockMetric(),
			steps: recordOf(PixelEventType, mockMetric),
			conversionRate: mockMetric(),
			carts: { count: mockMetric(), value: mockMetric() },
		}
	}
}

import { describe, it, expect } from 'bun:test'
import { TenancyScope, PixelEventType } from '@bk-dash/contracts-typescript/wire/enums'
import { GetPixelFunnel, GetPixelFunnelOutputSchema } from './GetPixelFunnel'

const STORE_ID = '11111111-1111-4111-8111-111111111111'
const STORE_IDS = ['11111111-1111-4111-8111-111111111111', '22222222-2222-4222-8222-222222222222']
const RANGE = { startDate: new Date('2026-05-01T00:00:00Z'), endDate: new Date('2026-05-31T00:00:00Z') }

function run(tenancyScope: TenancyScope, productIds?: string[]) {
	return new GetPixelFunnel().execute({ tenancyScope, storeId: STORE_ID, storeIds: STORE_IDS, ...RANGE, productIds })
}

describe('GetPixelFunnel', () => {
	it('returns a flat funnel that conforms to the schema (SINGLE)', async () => {
		const out = await run(TenancyScope.SINGLE_STORE)
		expect(() => GetPixelFunnelOutputSchema.parse(out)).not.toThrow()
		expect(out.hasPixel).toBe(true)
		expect(out.base).toHaveProperty('value')
		expect(out.carts).toHaveProperty('count')
		expect(out.carts).toHaveProperty('value')
	})

	it('has a step entry for every PixelEventType', async () => {
		const out = await run(TenancyScope.SINGLE_STORE)
		for (const stage of Object.values(PixelEventType)) {
			expect(out.steps[stage]).toHaveProperty('value')
		}
	})

	it('shape is identical for MULTI (tenancyScope is input-only)', async () => {
		const out = await run(TenancyScope.MULTI_STORE)
		expect(() => GetPixelFunnelOutputSchema.parse(out)).not.toThrow()
		expect(Object.keys(out)).toEqual(['hasPixel', 'base', 'steps', 'conversionRate', 'carts'])
	})

	it('is deterministic for the same inputs', async () => {
		const a = await run(TenancyScope.SINGLE_STORE, ['33333333-3333-4333-8333-333333333333'])
		const b = await run(TenancyScope.SINGLE_STORE, ['33333333-3333-4333-8333-333333333333'])
		expect(a).toEqual(b)
	})
})

/**
 * Dashboard read vocabulary. Each Stat KPI is `{ metric, details? }`; AdditionalCost is its own
 * top-level breakdown. National adds `paymentMethods` (under Stat) and `draftOrders` (under
 * AdditionalCost). Consolidated variants swap money leaves to CurrencyMetric.
 * Generic atoms (Metric/CurrencyMetric/Tally/segmented) come from @shared/schemas.
 */
import { z } from '@bk-dash/core-typescript'
import {
	CurrencyCode,
	CostKind,
	MarketingPlatform,
	AdAttribution,
	DisputeStatus,
	PaymentMethod,
	PaymentStatus,
	OperationalCostFlow,
	OperationalCostRecurrency,
} from '@bk-dash/contracts-typescript/wire/enums'
import { MetricSchema, CurrencyMetricSchema, TallySchema, ConsolidatedTallySchema, segmented } from '../../shared/schemas'

// ---------------------------------------------------------------------------
// Consolidated segmented helper (money leaves → CurrencyMetric)
// ---------------------------------------------------------------------------
const segmentedCurrency = <T extends Record<string, string>>(enumObject: T) =>
	z.object({ total: CurrencyMetricSchema, segments: z.enumRecord(enumObject, CurrencyMetricSchema) })

// ---------------------------------------------------------------------------
// Operational cost item
// ---------------------------------------------------------------------------
export const OperationalCostItemSchema = z.object({
	id: z.string(),
	name: z.string(),
	flow: z.enum(OperationalCostFlow),
	frequency: z.enum(OperationalCostRecurrency),
	amount: z.number(),
	currency: z.enum(CurrencyCode),
	startDate: z.iso.datetime({ offset: true }),
	endDate: z.iso.datetime({ offset: true }).nullable(),
})

// ---------------------------------------------------------------------------
// Stat — each KPI is `{ metric, details? }`. Money KPIs become CurrencyMetric when consolidated;
// ratios/counts (margin, roi, roas, unitsSold) stay Metric. orders/paymentMethods carry count +
// value, so their leaves are Tally.
// ---------------------------------------------------------------------------
export const StatSchema = z.object({
	revenue: z.object({ metric: MetricSchema }),
	profit: z.object({ metric: MetricSchema }),
	margin: z.object({ metric: MetricSchema }),
	averageTicket: z.object({ metric: MetricSchema }),
	unitsSold: z.object({ metric: MetricSchema }),
	roi: z.object({ metric: MetricSchema }),
	roas: z.object({ metric: MetricSchema }),
	costs: z.object({ metric: MetricSchema, details: segmented(CostKind) }),
	productCost: z.object({ metric: MetricSchema, details: z.object({ product: MetricSchema, shipping: MetricSchema }) }),
	fees: z.object({
		metric: MetricSchema,
		details: z.object({ gateway: MetricSchema, checkout: MetricSchema, chargeback: MetricSchema }),
	}),
	ads: z.object({
		metric: MetricSchema,
		details: z.object({
			byPlatform: segmented(MarketingPlatform),
			byType: segmented(AdAttribution),
			tax: MetricSchema,
			cpa: MetricSchema,
		}),
	}),
	orders: z.object({ metric: TallySchema, details: z.object({ generated: TallySchema, paid: TallySchema }) }),
})

const PaymentMethodsStatSchema = z.object({
	metric: TallySchema,
	details: z.object({
		byMethod: z.enumRecord(PaymentMethod, z.object({ total: TallySchema, byStatus: z.enumRecord(PaymentStatus, TallySchema) })),
	}),
})

/** NATIONAL adds the payment-method breakdown as a Stat entry. */
export const StatNationalSchema = StatSchema.extend({ paymentMethods: PaymentMethodsStatSchema })

/** Per-store Stat keyed by StoreIntegrationId (UUID string). Each store mono-currency. */
export const PerStoreStatSchema = z.record(z.string(), StatSchema)

// ---------------------------------------------------------------------------
// Consolidated Stat (multi-store) — money leaves → CurrencyMetric; ratios/counts stay Metric.
// ---------------------------------------------------------------------------
export const ConsolidatedStatSchema = z.object({
	revenue: z.object({ metric: CurrencyMetricSchema }),
	profit: z.object({ metric: CurrencyMetricSchema }),
	margin: z.object({ metric: MetricSchema }),
	averageTicket: z.object({ metric: CurrencyMetricSchema }),
	unitsSold: z.object({ metric: MetricSchema }),
	roi: z.object({ metric: MetricSchema }),
	roas: z.object({ metric: MetricSchema }),
	costs: z.object({ metric: CurrencyMetricSchema, details: segmentedCurrency(CostKind) }),
	productCost: z.object({
		metric: CurrencyMetricSchema,
		details: z.object({ product: CurrencyMetricSchema, shipping: CurrencyMetricSchema }),
	}),
	fees: z.object({
		metric: CurrencyMetricSchema,
		details: z.object({ gateway: CurrencyMetricSchema, checkout: CurrencyMetricSchema, chargeback: CurrencyMetricSchema }),
	}),
	ads: z.object({
		metric: CurrencyMetricSchema,
		details: z.object({
			byPlatform: segmentedCurrency(MarketingPlatform),
			byType: segmentedCurrency(AdAttribution),
			tax: CurrencyMetricSchema,
			cpa: MetricSchema,
		}),
	}),
	orders: z.object({
		metric: ConsolidatedTallySchema,
		details: z.object({ generated: ConsolidatedTallySchema, paid: ConsolidatedTallySchema }),
	}),
})

const ConsolidatedPaymentMethodsStatSchema = z.object({
	metric: ConsolidatedTallySchema,
	details: z.object({
		byMethod: z.enumRecord(
			PaymentMethod,
			z.object({ total: ConsolidatedTallySchema, byStatus: z.enumRecord(PaymentStatus, ConsolidatedTallySchema) }),
		),
	}),
})

export const ConsolidatedStatNationalSchema = ConsolidatedStatSchema.extend({ paymentMethods: ConsolidatedPaymentMethodsStatSchema })

// ---------------------------------------------------------------------------
// AdditionalCost — its own top-level. `draftOrders` only in *_NATIONAL.
// ---------------------------------------------------------------------------
export const AdditionalCostSchema = z.object({
	chargeback: z.object({ byStatus: segmented(DisputeStatus), fees: MetricSchema }),
	refund: MetricSchema,
	taxes: z.object({ ads: MetricSchema, others: MetricSchema }),
	operational: z.object({ total: MetricSchema, items: z.array(OperationalCostItemSchema) }),
	warranty: MetricSchema,
})

export const AdditionalCostNationalSchema = AdditionalCostSchema.extend({ draftOrders: TallySchema })

export const ConsolidatedAdditionalCostSchema = z.object({
	chargeback: z.object({ byStatus: segmentedCurrency(DisputeStatus), fees: CurrencyMetricSchema }),
	refund: CurrencyMetricSchema,
	taxes: z.object({ ads: CurrencyMetricSchema, others: CurrencyMetricSchema }),
	operational: z.object({ total: CurrencyMetricSchema, items: z.array(OperationalCostItemSchema) }),
	warranty: CurrencyMetricSchema,
})

export const ConsolidatedAdditionalCostNationalSchema = ConsolidatedAdditionalCostSchema.extend({
	draftOrders: ConsolidatedTallySchema,
})

