	margin: { metric: fakeMetric() },
	averageTicket: { metric: fakeMetric() },
	unitsSold: { metric: fakeMetric() },
	roi: { metric: fakeMetric() },
	roas: { metric: fakeMetric() },
	costs: { metric: fakeMetric(), details: segmentedMetric(CostKind) },
	productCost: { metric: fakeMetric(), details: { product: fakeMetric(), shipping: fakeMetric() } },
	fees: { metric: fakeMetric(), details: { gateway: fakeMetric(), checkout: fakeMetric(), chargeback: fakeMetric() } },
