})

// ----- AdditionalCost -----
const fakeAdditionalCostBase = () => ({
	chargeback: { byStatus: segmentedMetric(DisputeStatus), fees: fakeMetric() },
	refund: fakeMetric(),
	taxes: { ads: fakeMetric(), others: fakeMetric() },
	operational: { total: fakeMetric(), items: mockSeries(3, fakeOperationalItem) },
	warranty: fakeMetric(),
})
const fakeAdditionalCost = (): Z.infer<typeof AdditionalCostSchema> => fakeAdditionalCostBase()
const fakeAdditionalCostNational = (): Z.infer<typeof AdditionalCostNationalSchema> => ({
	...fakeAdditionalCostBase(),
	draftOrders: fakeTally(),
})

const fakeConsolidatedAdditionalCostBase = () => ({
	chargeback: { byStatus: segmentedCurrency(DisputeStatus), fees: fakeCurrencyMetric() },
	refund: fakeCurrencyMetric(),
