const fakeConsolidatedAdditionalCostNational = (): Z.infer<typeof ConsolidatedAdditionalCostNationalSchema> => ({
	...fakeConsolidatedAdditionalCostBase(),
	draftOrders: fakeConsolidatedTally(),
})

const fakePerStore = (storeIds: string[]): Z.infer<typeof PerStoreStatSchema> => Object.fromEntries(storeIds.map(id => [id, fakeStat()]))

/** Deterministic seed from the request so refetches return stable fixtures. */
const seedFrom = (parts: string[]): number => {
	const s = parts.join('|')
	let h = 0
	for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0
	return Math.abs(h) || 1
}

/**
 * `GetDashboard` — composition-first discriminated dashboard read.
 *
 * FAKER body, REAL contract: `tenancyScope` (query) selects SINGLE vs MULTI
 * store shape; `dashboardMode` is read from the persisted `StoreVisualization`
 * (default GLOBAL) and toggles the NATIONAL extensions (`stat.paymentMethods`,
 * `additionalCost.draftOrders`). Real cross-context aggregation is a later swap.
 */
@injectable()
export class GetDashboard extends Handler<typeof GetDashboardInputSchema, typeof GetDashboardOutputSchema> {
	readonly name = 'get_dashboard' as const
	readonly inputSchema = GetDashboardInputSchema
	readonly outputSchema = GetDashboardOutputSchema

	constructor(private readonly visualizations: StoreVisualizationRepository) {
		super()
	}

	protected async handle(input: this['input']): Promise<this['output']> {
		faker.seed(seedFrom([input.storeId, input.startDate.toISOString(), input.endDate.toISOString(), ...(input.productIds ?? [])]))

		const visualization = await this.visualizations.findByStoreId(input.storeId)
		const dashboardMode = visualization?.dashboardMode ?? DashboardMode.GLOBAL
		const isMulti = input.tenancyScope === TenancyScope.MULTI_STORE
		const isNational = dashboardMode === DashboardMode.NATIONAL
		const kind = `${isMulti ? 'MULTI' : 'SINGLE'}_${dashboardMode}`

		const result = isMulti
			? {
					kind,
					tenancyScope: TenancyScope.MULTI_STORE,
					dashboardMode,
					stat: isNational ? fakeConsolidatedStatNational() : fakeConsolidatedStat(),
					perStore: fakePerStore(input.storeIds),
					additionalCost: isNational ? fakeConsolidatedAdditionalCostNational() : fakeConsolidatedAdditionalCost(),
				}
			: {
					kind,
					tenancyScope: TenancyScope.SINGLE_STORE,
					dashboardMode,
					store: { id: input.storeId, currency: pick(Object.values(CurrencyCode)) },
					stat: isNational ? fakeStatNational() : fakeStat(),
					additionalCost: isNational ? fakeAdditionalCostNational() : fakeAdditionalCost(),
				}

		return result as this['output']
	}
}

import { describe, it, expect } from 'bun:test'
import { TenancyScope, DashboardMode } from '@bk-dash/contracts-typescript/wire/enums'
import { GetDashboard, GetDashboardOutputSchema } from './GetDashboard'
import { MockStoreVisualizationRepository } from '../repositories/StoreVisualizationRepository/MockStoreVisualizationRepository'
import { StoreVisualization } from '../entities/StoreVisualization'

const STORE_ID = '11111111-1111-4111-8111-111111111111'
const STORE_IDS = ['11111111-1111-4111-8111-111111111111', '22222222-2222-4222-8222-222222222222']
const RANGE = { startDate: new Date('2026-05-01T00:00:00Z'), endDate: new Date('2026-05-31T00:00:00Z') }

function makeUseCase(persistedMode?: DashboardMode): GetDashboard {
	const repo = new MockStoreVisualizationRepository()
	if (persistedMode) repo.seed(StoreVisualization.create({ storeId: STORE_ID, dashboardMode: persistedMode }))
	return new GetDashboard(repo)
}

function run(tenancyScope: TenancyScope, persistedMode?: DashboardMode) {
	return makeUseCase(persistedMode).execute({ tenancyScope, storeId: STORE_ID, storeIds: STORE_IDS, ...RANGE })
}

describe('GetDashboard', () => {
	it('SINGLE + default (no persisted row) → SINGLE_GLOBAL: store + stat + details, no paymentMethods/perStore', async () => {
		const out = await run(TenancyScope.SINGLE_STORE)
		expect(out.kind).toBe('SINGLE_GLOBAL')
		expect(out.tenancyScope).toBe(TenancyScope.SINGLE_STORE)
		expect(out.dashboardMode).toBe(DashboardMode.GLOBAL)
		expect('store' in out).toBe(true)
		expect('stat' in out).toBe(true)
		expect('additionalCost' in out).toBe(true)
		expect('paymentMethods' in (out as { stat: object }).stat).toBe(false)
		expect('draftOrders' in (out as { additionalCost: object }).additionalCost).toBe(false)
		expect('perStore' in out).toBe(false)
	})

	it('SINGLE + persisted NATIONAL → SINGLE_NATIONAL: adds stat.paymentMethods + additionalCost.draftOrders', async () => {
		const out = await run(TenancyScope.SINGLE_STORE, DashboardMode.NATIONAL)
		expect(out.kind).toBe('SINGLE_NATIONAL')
		expect(out.dashboardMode).toBe(DashboardMode.NATIONAL)
		expect('paymentMethods' in (out as { stat: object }).stat).toBe(true)
		expect('draftOrders' in (out as { additionalCost: object }).additionalCost).toBe(true)
	})

	it('MULTI + default → MULTI_GLOBAL: perStore (keyed by storeIds) + no store, no paymentMethods', async () => {
		const out = await run(TenancyScope.MULTI_STORE)
		expect(out.kind).toBe('MULTI_GLOBAL')
		expect('perStore' in out).toBe(true)
		expect('store' in out).toBe(false)
		expect('paymentMethods' in out).toBe(false)
		expect(Object.keys((out as { perStore: Record<string, unknown> }).perStore).sort()).toEqual([...STORE_IDS].sort())
	})

	it('MULTI + persisted NATIONAL → MULTI_NATIONAL: perStore + stat.paymentMethods + additionalCost.draftOrders', async () => {
		const out = await run(TenancyScope.MULTI_STORE, DashboardMode.NATIONAL)
		expect(out.kind).toBe('MULTI_NATIONAL')
		expect('perStore' in out).toBe(true)
		expect('paymentMethods' in (out as { stat: object }).stat).toBe(true)
		expect('draftOrders' in (out as { additionalCost: object }).additionalCost).toBe(true)
	})

	it('faker output conforms to the discriminated-union schema', async () => {
		for (const scope of [TenancyScope.SINGLE_STORE, TenancyScope.MULTI_STORE]) {
			for (const mode of [DashboardMode.GLOBAL, DashboardMode.NATIONAL]) {
				const out = await run(scope, mode)
				expect(() => GetDashboardOutputSchema.parse(out)).not.toThrow()
			}
		}
	})

	it('is deterministic for the same inputs (seeded faker)', async () => {
		const a = await run(TenancyScope.SINGLE_STORE)
		const b = await run(TenancyScope.SINGLE_STORE)
		expect(a).toEqual(b)
	})
})

import { injectable } from 'tsyringe-neo'
import Z from 'zod'
