import { TenancyScope } from '@bk-dash/contracts-typescript/wire/enums'
import { TallySchema } from '../../shared/schemas'
import { faker, mockId, mockMetric, mockSeries } from '../../shared/testing/mock'

// ---------------------------------------------------------------------------
// Input — `tenancyScope` input-only (selects store set; output unchanged).
// ---------------------------------------------------------------------------
export const ListQuickProductRankingInputSchema = z.object({
	tenancyScope: z.enum(TenancyScope),
	storeId: z.uuid(), // ← ctx.session.storeId      (SINGLE_STORE)
	storeIds: z.array(z.uuid()), // ← ctx.membership.storeIds  (MULTI_STORE)
	startDate: z.date(),
	endDate: z.date(),
	productIds: z.array(z.uuid()).optional(),
})

// ---------------------------------------------------------------------------
// Output — top 10 by revenue desc (dashboard preview; full list = /app/products).
// ---------------------------------------------------------------------------
export const QuickProductRankingItemSchema = z.object({
	productId: z.uuid(),
	name: z.string(),
	imageUrl: z.url().nullable(),
	sales: TallySchema, // count = units sold (+ deltaPct), value = revenue (+ deltaPct)
})

export const ListQuickProductRankingOutputSchema = z.object({
	totalProducts: z.number(),
	items: z.array(QuickProductRankingItemSchema),
})

const seedFrom = (parts: string[]): number => {
	const s = parts.join('|')
	let h = 0
	for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0
	return Math.abs(h) || 1
}

const fakeItem = (): Z.infer<typeof QuickProductRankingItemSchema> => ({
	productId: mockId(),
	name: faker.commerce.productName(),
	imageUrl: faker.datatype.boolean() ? faker.image.url() : null,
	sales: { count: mockMetric(), value: mockMetric() },
})

/**
 * `ListQuickProductRanking` — dashboard RankingSection preview (top 10 by revenue).
 * FAKER body, REAL contract. `tenancyScope` selects the store set; output shape is
 * scope-independent. Real swap: sales OrderQueryService (units/revenue per product)
 * joined to catalog ProductQueryService, ordered by revenue, top 10.
 */
@injectable()
export class ListQuickProductRanking extends Handler<
	typeof ListQuickProductRankingInputSchema,
	typeof ListQuickProductRankingOutputSchema
> {
	readonly name = 'list_quick_product_ranking' as const
	readonly inputSchema = ListQuickProductRankingInputSchema
	readonly outputSchema = ListQuickProductRankingOutputSchema

	protected async handle(input: this['input']): Promise<this['output']> {
		const storeIds = input.tenancyScope === TenancyScope.MULTI_STORE ? input.storeIds : [input.storeId]
		faker.seed(seedFrom([...storeIds, input.startDate.toISOString(), input.endDate.toISOString(), ...(input.productIds ?? [])]))

		const items = mockSeries(10, fakeItem).sort((a, b) => b.sales.value.value - a.sales.value.value)
		return {
			totalProducts: faker.number.int({ min: 10, max: 500 }),
			items,
		}
	}
}

