import { describe, it, expect } from 'bun:test'
import { TenancyScope } from '@bk-dash/contracts-typescript/wire/enums'
import { ListQuickProductRanking, ListQuickProductRankingOutputSchema } from './ListQuickProductRanking'

const STORE_ID = '11111111-1111-4111-8111-111111111111'
const STORE_IDS = ['11111111-1111-4111-8111-111111111111', '22222222-2222-4222-8222-222222222222']
const RANGE = { startDate: new Date('2026-05-01T00:00:00Z'), endDate: new Date('2026-05-31T00:00:00Z') }

function run(tenancyScope: TenancyScope, productIds?: string[]) {
	return new ListQuickProductRanking().execute({ tenancyScope, storeId: STORE_ID, storeIds: STORE_IDS, ...RANGE, productIds })
}

describe('ListQuickProductRanking', () => {
	it('returns exactly 10 items conforming to the schema', async () => {
		const out = await run(TenancyScope.SINGLE_STORE)
		expect(() => ListQuickProductRankingOutputSchema.parse(out)).not.toThrow()
		expect(out.items).toHaveLength(10)
		expect(typeof out.totalProducts).toBe('number')
	})

	it('items carry sales as a Tally (units count + revenue value)', async () => {
		const out = await run(TenancyScope.SINGLE_STORE)
		const first = out.items[0]
		expect(first?.sales.count).toHaveProperty('value')
		expect(first?.sales.value).toHaveProperty('value')
	})

	it('is ranked by revenue desc', async () => {
		const out = await run(TenancyScope.SINGLE_STORE)
		const revenues = out.items.map(i => i.sales.value.value)
		const sorted = [...revenues].sort((a, b) => b - a)
		expect(revenues).toEqual(sorted)
	})

	it('shape is scope-independent (MULTI also 10 items)', async () => {
		const out = await run(TenancyScope.MULTI_STORE)
		expect(out.items).toHaveLength(10)
	})

	it('is deterministic for the same inputs', async () => {
		const a = await run(TenancyScope.SINGLE_STORE, ['33333333-3333-4333-8333-333333333333'])
