	'MULTI_NATIONAL',
	TenancyScope.MULTI_STORE,
	DashboardMode.NATIONAL,
	STAT_CONSOLIDATED_NATIONAL,
	ADDITIONAL_CONSOLIDATED_NATIONAL,
)

