import { createFileRoute } from '@tanstack/react-router'
import { endOfDay, startOfDay, subDays } from 'date-fns'
import { getDashboardQueryParamsSchema } from '@bk-dash/client-typescript/typescript'
import { z } from 'zod'

// Dashboard period + product filter live in the URL so the view is bookmarkable. Derived from the
// SDK's GetDashboard query-params schema (so productIds stays in sync): drop tenancyScope (it is an
// app-global store — see @/stores/useTenancyStore) and the required dates, then `.and` defaulted
// dates (last 30 days). Exported so the Storybook story mounts the data under a matching router.
export const dashboardSearchSchema = getDashboardQueryParamsSchema.omit({ tenancyScope: true, startDate: true, endDate: true }).and(
	z.object({
		startDate: z.string().default(() => startOfDay(subDays(new Date(), 29)).toISOString()),
		endDate: z.string().default(() => endOfDay(new Date()).toISOString()),
	}),
)

export const Route = createFileRoute('/(app)/dashboard/')({
	validateSearch: search => dashboardSearchSchema.parse(search ?? {}),
	component: RouteComponent,
})

// Mock route shell — the real screen (incl. the Additional Costs card) is showcased in Storybook
// and not yet wired into this route.
function RouteComponent() {
	return (
		<div className="p-8 flex flex-col gap-2">
			<h1 className="text-xl font-bold text-foreground">Dashboard</h1>
			<p className="text-muted-foreground">Mock route — to be implemented.</p>
		</div>
	)
}

