#!/usr/bin/env bun

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { build, writeOutputs } from '../core/builder'
import { deserializeGraph, type Graph, type SerializedGraph } from '../core/graph'
import { GRAPH_JSON, GRAPH_OUT, repoRelative } from '../core/paths'
import { buildAdjacency, downstream, orphans, renderTree, shortestPath, upstream } from '../core/query'
import { renderGraphHtml } from '../outputs/html'
import {
	changedFilesFromDiff,
	changedFilesUnstaged,
	formatMeasurement,
	formatReviewBatch,
	loadQueryContext,
	measureReviewBatch,
	reviewBatch,
	reviewFile,
} from '../core/review-query'
import { buildPlanPayload } from './plan-cmd'
import { parsePlan } from './plan-parser'
import { validatePlan } from './validate-plan-cmd'

const args = process.argv.slice(2)
const command = args[0]

async function loadOrBuild(): Promise<Graph> {
	if (!existsSync(GRAPH_JSON)) {
		console.error('Graph file not found, building from scratch...')
		const result = await build()
		writeOutputs(result)
		return result.graph
	}
	const raw = readFileSync(GRAPH_JSON, 'utf8')
	return deserializeGraph(JSON.parse(raw) as SerializedGraph)
}

function jsonOut(value: unknown): void {
	process.stdout.write(JSON.stringify(value, null, 2))
	process.stdout.write('\n')
}

function parseDepthFlag(args: string[], fallback: number): number {
	return parseIntFlag(args, '--depth', fallback)
}

function parseIntFlag(args: string[], flag: string, fallback: number): number {
	const eq = args.find(a => a.startsWith(`${flag}=`))
	if (eq) {
		const n = parseInt(eq.slice(flag.length + 1), 10)
		if (!Number.isNaN(n)) return n
	}
	const idx = args.indexOf(flag)
	if (idx >= 0 && args[idx + 1]) {
		const n = parseInt(args[idx + 1]!, 10)
		if (!Number.isNaN(n)) return n
	}
	return fallback
}

async function main() {
	switch (command) {
		case 'build': {
			console.log('Building code graph...')
			const start = Date.now()
			const result = await build()
			writeOutputs(result)
			const elapsed = Date.now() - start
			console.log()
			console.log(`Graph built in ${elapsed}ms`)
			console.log(`  Nodes: ${result.stats.nodes}`)
			console.log(`  Edges: ${result.stats.edges}`)
			console.log(`  Backend (TS) files: ${result.stats.extractor.backend}`)
			console.log(`  Backend (Go) files: ${result.stats.extractor.go}`)
			console.log(`  Frontend files: ${result.stats.extractor.frontend}`)
			console.log(`  Astro files: ${result.stats.extractor.astro}`)
			console.log(`  DB tables: ${result.stats.extractor.drizzle}`)
			console.log(
				`  Contracts: ${result.stats.extractor.contracts.enums} enums, ${result.stats.extractor.contracts.events} events, ${result.stats.extractor.contracts.unions} unions, ${result.stats.extractor.contracts.generatedLinked} generated edges`,
			)
			console.log(`  Locale keys: ${result.stats.extractor.locale}`)
			console.log(`  SDK operations: ${result.stats.extractor.openapi}`)
			console.log(
				`  Resolver: ${result.stats.resolve.upgraded} upgraded, ${result.stats.resolve.derived} derived, ${result.stats.resolve.pruned} pruned, ${result.stats.resolve.rewired} rewired`,
			)
			console.log()
			console.log(`Output: ${GRAPH_JSON}`)
			return
		}
		case 'why': {
			const id = args[1]
			if (!id) {
				console.error('Usage: bun cli graph why <node-id> [depth=4] [--json]')
				process.exit(1)
			}
			const json = args.includes('--json')
			const depth = parseDepthFlag(args, parseInt(args[2] ?? '4', 10))
			const graph = await loadOrBuild()
			const adj = buildAdjacency(graph)
			const result = upstream(graph, adj, id, depth)
			if (!result) {
				console.error(`Node not found: ${id}`)
				process.exit(1)
			}
			if (json) {
				jsonOut(result)
				return
			}
			console.log(`Why ${result.root.id} exists (upstream depth ${depth}):`)
			console.log(renderTree(result.tree))
			return
		}
		case 'impact': {
			const id = args[1]
			if (!id) {
				console.error('Usage: bun cli graph impact <node-id> [depth=4] [--json]')
				process.exit(1)
			}
			const json = args.includes('--json')
			const depth = parseDepthFlag(args, parseInt(args[2] ?? '4', 10))
			const graph = await loadOrBuild()
			const adj = buildAdjacency(graph)
			const result = downstream(graph, adj, id, depth)
			if (!result) {
				console.error(`Node not found: ${id}`)
				process.exit(1)
			}
			if (json) {
				jsonOut(result)
				return
			}
			console.log(`Impact of changing ${result.root.id} (downstream depth ${depth}):`)
			console.log(renderTree(result.tree))
			return
		}
		case 'path': {
			const a = args[1]
			const b = args[2]
			if (!a || !b) {
				console.error('Usage: bun cli graph path <from-id> <to-id> [--directed]')
				process.exit(1)
			}
			const directed = args.includes('--directed')
			const graph = await loadOrBuild()
			const adj = buildAdjacency(graph)
			const path = shortestPath(graph, adj, a, b, { directed })
			if (!path) {
				console.log(`No path from ${a} to ${b}`)
				return
			}
			console.log(`Path from ${a} to ${b}${directed ? ' (directed)' : ' (undirected)'}:`)
			let cursor = a
			for (const step of path) {
				const arrow = step.reversed ? '←' : '→'
				const next = step.reversed ? step.edge.from : step.edge.to
				const audit = step.edge.audit === 'INFERRED' ? '*' : ''
				console.log(`  ${cursor}\n    ─[${step.edge.kind}${audit}]${arrow}\n  ${next}`)
				cursor = next
			}
			return
		}
		case 'orphans': {
			const json = args.includes('--json')
			const includeByDesign = args.includes('--all')
			const graph = await loadOrBuild()
			const adj = buildAdjacency(graph)
			const result = orphans(graph, adj, { includeByDesign })
			if (json) {
				jsonOut(result)
				return
			}
			console.log(`Orphan nodes (${result.length}${includeByDesign ? ', incl. by-design' : ', excl. generated/dead'}):`)
			for (const node of result) {
				console.log(`  ${node.id}  (${node.kind}, ${node.location?.file ?? 'no location'})`)
			}
			return
		}
		case 'file': {
			const fileArg = args[1]
			if (!fileArg) {
				console.error('Usage: bun cli graph file <path> [--json] [--depth=3] [--max-downstream=50]')
				process.exit(1)
			}
			const json = args.includes('--json')
			const depth = parseDepthFlag(args, 3)
			const maxDownstream = parseIntFlag(args, '--max-downstream', 50)
			const ctx = loadQueryContext()
			const repoPath = fileArg.startsWith('/') ? repoRelative(fileArg) : fileArg
			const result = reviewFile(ctx, repoPath, { depth, maxDownstream })
			if (json) {
				jsonOut(result)
				return
			}
			if (result.nodes.length === 0) {
				console.log(`(no graph nodes for ${result.file})`)
				return
			}
			console.log(`# ${result.file}`)
			for (const n of result.nodes) {
				console.log(`\n${n.node.id}`)
				console.log(`  kind: ${n.node.kind}`)
				if (n.skill) console.log(`  skill: ${n.skill}`)
				console.log(`  ↑ ${n.incoming.length} upstream · ↓ ${n.outgoing.length} downstream`)
				const td = n.transitiveDownstream
				const note = td.truncated ? ` (sample of ${td.nodes.length} shown)` : ''
				console.log(`  blast radius: ${td.count} nodes${note} (depth ${depth})`)
			}
			return
		}
		case 'review': {
			// `graph review` — produce a review payload for changed files
			//   --diff <ref>      compare HEAD against <ref> (default behaviour: unstaged)
			//   --files <a> <b>   explicit file list
			//   --json            emit machine-readable JSON
			//   --measure         emit a payload-size breakdown (bytes/tokens by section)
			//   --depth=N         BFS depth for transitive impact (default 3)
			const json = args.includes('--json')
			const measure = args.includes('--measure')
			const depth = parseDepthFlag(args, 3)
			const maxDownstream = parseIntFlag(args, '--max-downstream', 50)
			const filesIdx = args.indexOf('--files')
			const diffIdx = args.indexOf('--diff')

			let files: string[] = []
			if (filesIdx >= 0) {
				files = args.slice(filesIdx + 1).filter(a => !a.startsWith('--'))
			} else if (diffIdx >= 0) {
				const ref = args[diffIdx + 1]
				if (!ref || ref.startsWith('--')) {
					console.error('Usage: bun cli graph review --diff <git-ref> [--json] [--depth=N]')
					process.exit(1)
				}
				files = changedFilesFromDiff(ref)
			} else {
				files = changedFilesUnstaged()
			}

			if (files.length === 0) {
				console.error('No changed files detected. Use --files or --diff <ref>.')
				process.exit(1)
			}

			const ctx = loadQueryContext()
			const batch = reviewBatch(ctx, files, { depth, maxDownstream })
			if (measure) {
				process.stdout.write(formatMeasurement(measureReviewBatch(batch)))
				return
			}
			if (json) {
				jsonOut(batch)
				return
			}
			process.stdout.write(formatReviewBatch(batch))
			return
		}
		case 'render': {
			const graph = await loadOrBuild()
			const html = renderGraphHtml(graph)
			mkdirSync(GRAPH_OUT, { recursive: true })
			const outPath = join(GRAPH_OUT, 'index.html')
			writeFileSync(outPath, html)
			console.log(`HTML viewer written to ${outPath}`)
			console.log(`Open with: open ${outPath}`)
			return
		}
		case 'stats': {
			const graph = await loadOrBuild()
			console.log('Graph stats')
			console.log(`  Nodes: ${graph.nodes.size}`)
			console.log(`  Edges: ${graph.edges.length}`)
			console.log()
			console.log('  Nodes by kind:')
			const byKind = Object.entries(graph.stats.nodesByKind).sort((a, b) => b[1] - a[1])
			for (const [kind, count] of byKind) {
				console.log(`    ${kind.padEnd(28)} ${count}`)
			}
			console.log()
			console.log('  Edges by kind:')
			const byEdge = Object.entries(graph.stats.edgesByKind).sort((a, b) => b[1] - a[1])
			for (const [kind, count] of byEdge) {
				console.log(`    ${kind.padEnd(28)} ${count}`)
			}
			return
		}
		case 'plan': {
			const specPath = args[1]
			if (!specPath) {
				console.error('usage: graph plan <spec-path> [--json]')
				process.exit(2)
			}
			const payload = await buildPlanPayload(specPath)
			if (args.includes('--json')) {
				jsonOut(payload)
			} else {
				console.log(`Graph snapshot for ${specPath}`)
				console.log(`  Nodes: ${payload.graphStats.nodeCount}, edges: ${payload.graphStats.edgeCount}`)
				console.log(`  Contexts: ${payload.graphStats.contexts.join(', ')}`)
				console.log(`  Skill registries loaded: ${Object.keys(payload.registries).length}`)
				console.log(`  Existing artifacts: ${payload.existingArtifacts.length}`)
				if (payload.inconsistencies.length > 0) {
					console.log(`  Inconsistencies: ${payload.inconsistencies.length}`)
					for (const i of payload.inconsistencies.slice(0, 10)) console.log(`    - ${i.kind}: ${i.message}`)
				}
			}
			return
		}
		case 'validate-plan': {
			const planPath = args[1]
			if (!planPath) {
				console.error('usage: graph validate-plan <plan-path>')
				process.exit(2)
			}
			const result = await validatePlan(planPath)
			if (result.findings.length > 0) {
				console.error(JSON.stringify(result.findings, null, 2))
			} else {
				console.log(`OK: ${planPath} passes PR-18..21`)
			}
			process.exit(result.exitCode)
			return
		}
		case 'parse-plan': {
			const planPath = args[1]
			if (!planPath) {
				console.error('usage: graph parse-plan <plan-path> [--json]')
				process.exit(2)
			}
			const raw = readFileSync(planPath, 'utf8')
			const ast = parsePlan(raw)
			if (args.includes('--json')) {
				jsonOut(ast)
			} else {
				console.log(`Plan: ${ast.title}`)
				console.log(`  Spec: ${ast.specPath}`)
				console.log(`  Tasks: ${ast.tasks.length}`)
				for (const t of ast.tasks) {
					console.log(`    ${t.id} — ${t.name} [${t.agent}] (${t.steps.length} steps, deps: ${t.dependsOn.join(',') || 'none'})`)
				}
				console.log(`  Final validation steps: ${ast.finalValidation.length}`)
			}
			return
		}
		case 'help':
		case '--help':
		case '-h':
		case undefined:
			showHelp()
			return
		default:
			console.error(`Unknown command: ${command}`)
			showHelp()
			process.exit(1)
	}
}

function showHelp() {
	console.log(`
Graph CLI — Codebase code-graph extractor & query

USAGE:
  bun cli graph <command> [args]

COMMANDS:
  build                                Extract the full code graph (writes .graph/graph.json + index.json)
  why <node-id> [depth=4] [--json]     Show upstream tree (what depends on this)
  impact <node-id> [depth=4] [--json]  Show downstream tree (what breaks if this changes)
  path <from-id> <to-id>               Shortest connecting path
  orphans [--json]                     List nodes with no edges
  stats                                Graph stats (nodes/edges by kind)
  file <path> [--json] [--depth=N]     Per-file review payload (nodes, deps, skill registry)
  review [--diff <ref>] [--files ...]  Batch review for changed files (use --json for piping)
        [--json] [--measure] [--depth=N] [--max-downstream=N]
                                         (--measure prints a payload size breakdown;
                                          --max-downstream caps transitiveDownstream sampling, default 50)
  render                               Generate interactive HTML viewer at .graph/index.html

NODE ID FORMAT (polyglot):
  <workspace>:<ctx>:<kind>:<name>      e.g. api-go:sales:entity:Order
  <workspace>:<kind>:<name>            e.g. app-react:frontend-section:OrderList
  <workspace>:frontend-route:<path>    e.g. app-react:frontend-route:packages/app/react/src/routes/index
  sdk:<sdkLang>:<backendLang>:...      e.g. sdk:go:typescript:sdk-operation:listOrders
  sdk:app:<kind>:<name>                e.g. sdk:app:sdk-hook:useListVideos  (TS→TS legacy alias)
  contracts:<kind>:<name>              e.g. contracts:contract-enum:VideoStatus
  db:<schema>:db-table:<symbol>        e.g. db:video:db-table:videos
  docs:locale:<lang>:<dotted.key>      e.g. docs:locale:pt:errors.VIDEO_NOT_FOUND

WORKSPACES (matrix):
  api-typescript | api-go                         backends
  app-react | app-expo | app-astro                frontends
  contracts                                       wire + db source of truth
  client-typescript | client-go                   generated SDKs
  contracts-generated-{ts,go}                     generated wire bindings
`)
}

main().catch(err => {
	console.error(err)
	process.exit(1)
})

import { existsSync, readFileSync } from 'node:fs'
import { join } from 'node:path'
import { parsePlan, type PlanTask } from './plan-parser'
import { loadQueryContext } from '../core/review-query'
import { buildAdjacency } from '../core/query'
import { ROOT } from '../core/paths'

export type ValidationFinding = {
	rule: 'PR-18' | 'PR-19' | 'PR-20' | 'PR-21' | 'PR-26' | 'PR-27'
	taskId: string
	detail: string
	path?: string
}

/**
 * Map a frontend file path to the `bun cli` verb that scaffolds it, or null when the
 * path is not a scaffoldable frontend artifact. Helpers (`lib/`), hooks (`-hooks/`),
 * colocated logic modules, barrels (`index.ts`), tests, stories, locale JSON, and
 * generated files all return null — only the artifact ENTRY files map to a verb.
 */
function scaffoldableFrontendVerb(filePath: string): 'component' | 'route' | 'store' | 'form' | 'primitive' | null {
	if (!filePath.startsWith('packages/app/')) return null
	if (/\.(test|spec)\.[jt]sx?$|\.stories\.[jt]sx?$|\/locales\/|routeTree\.gen\./.test(filePath)) return null
	const base = filePath.split('/').pop() ?? ''
	if (/\/-components\//.test(filePath) && base === 'index.tsx') return 'component'
	if (/\/-forms\//.test(filePath) && base === 'index.tsx') return 'form'
	if (/(\/stores\/|\/-stores\/)/.test(filePath) && base !== 'index.ts' && /\.tsx?$/.test(base)) return 'store'
	if (/\/components\/ui\//.test(filePath) && /\.tsx$/.test(base)) return 'primitive'
	if (/\/routes\//.test(filePath) && (base === 'index.tsx' || base === 'route.tsx')) return 'route'
	return null
}

export type ValidationResult = {
	exitCode: number
	findings: ValidationFinding[]
}

// ── Domain Mapping parser ──

type DomainMappingEntry = {
	/** Row index (1-based) */
	index: number
	action: 'create' | 'modify' | 'read-only'
	skill: string
	name: string
	context: string
	path?: string
}

/**
 * Parse the Domain Mapping table from the plan markdown.
 * Returns an empty array if the section is absent (bootstrap plans omit it).
 *
 * Expected format (from plan.md Plan Format):
 *   | # | Action | Skill | Name | Context | Story / Decision / AC |
 *   |---|--------|-------|------|---------|------------------------|
 *   | 1 | create | /entity | Foo | bar | Story 1 |
 */
function parseDomainMapping(raw: string): DomainMappingEntry[] {
	const domainSection = /^## Domain Mapping/m.exec(raw)
	if (!domainSection) return []

	const sectionStart = domainSection.index
	// Find the next ## heading after the Domain Mapping section
	const nextHeading = /^## /m.exec(raw.slice(sectionStart + 1))
	const sectionEnd = nextHeading ? sectionStart + 1 + nextHeading.index : raw.length

	const section = raw.slice(sectionStart, sectionEnd)

	const entries: DomainMappingEntry[] = []
	// Each column accepts any non-pipe content (so prose like "(PATCH ...)"
	// after the identifier doesn't silently drop the row). Tokens are
	// trimmed and identifiers extracted by the matcher downstream.
	const tableRowRe = /^\|\s*(\d+)\s*\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|/gm
	for (const match of section.matchAll(tableRowRe)) {
		const action = match[2]!.toLowerCase() as DomainMappingEntry['action']
		if (action !== 'create' && action !== 'modify' && action !== 'read-only') continue
		entries.push({
			index: parseInt(match[1]!, 10),
			action,
			skill: match[3]!.replace(/^\//, ''),
			name: match[4]!,
			context: match[5]!,
		})
	}
	return entries
}

/**
 * Extract the leading identifier from a Domain Mapping name.
 * "UpdateAppointmentNotesController (PATCH ...)" → "updateappointmentnotescontroller"
 * "Money" → "money"
 */
function identifierFromName(name: string): string {
	const head = name.split(/[\s(]/)[0] ?? name
	return head.toLowerCase()
}

/**
 * File stem = basename without extensions. Strips everything from the
 * first dot, so "Appointment.test.ts" → "appointment",
 * "AppointmentNotesUpdated.ts" → "appointmentnotesupdated".
 */
function stemOf(filePath: string): string {
	const base = filePath.split('/').pop() ?? ''
	return base.replace(/\..*$/, '').toLowerCase()
}

/**
 * Path-segment hints per skill: when a Domain Mapping entry's skill
 * implies a specific directory pattern (e.g., /controller → /controllers/),
 * require the file path to match the pattern. This disambiguates entries
 * whose `name` produces the same stem in different layers (notably the
 * /ui context convention where controller and query share the basename,
 * e.g., ui/controllers/appointments/ListAppointments.ts and
 * ui/usecases/appointments/ListAppointments.ts).
 */
const SKILL_PATH_HINTS: Record<string, RegExp> = {
	controller: /\/controllers\//,
	usecase: /\/usecases\//,
	query: /\/usecases\//, // queries live under ui/usecases in this monorepo
	entity: /\/entities\//,
	'value-object': /\/objects\//,
	enum: /\/enums\//,
	repository: /\/repositories\//,
	schema: /\/schemas\//,
	errors: /\/errors\//,
	event: /\/events\//,
	handler: /\/handlers\//,
	service: /\/services\//,
	route: /\/routes\//,
	component: /-components\//,
	form: /-forms\//,
	store: /-stores\//,
	primitive: /\/primitives\//,
	job: /\/jobs\//,
}

/**
 * Build a mapping of proposed paths → Domain Mapping action.
 * We match paths to Domain Mapping entries by correlating each Task's
 * filesWrites with Domain Mapping entries using name/context matching
 * or fall back to inspecting the path segments.
 *
 * Since the plan format doesn't embed proposedPath in the Domain Mapping
 * table, we need a heuristic: a filesWrites path is "new" if Domain Mapping
 * marks the corresponding artifact as `create`, "modify" if marked `modify`.
 *
 * Heuristic: match by artifact name appearing in the file path and context.
 */
function buildPathActionMap(tasks: PlanTask[], domainEntries: DomainMappingEntry[]): Map<string, DomainMappingEntry['action']> {
	const map = new Map<string, DomainMappingEntry['action']>()

	if (domainEntries.length === 0) {
		// No Domain Mapping table — assume all writes are new artifacts
		for (const task of tasks) {
			for (const p of task.filesWrites) {
				map.set(p, 'create')
			}
		}
		return map
	}

	// Index entries by lowercase name and context for matching
	const byNameCtx = new Map<string, DomainMappingEntry>()
	for (const entry of domainEntries) {
		byNameCtx.set(`${entry.name.toLowerCase()}:${entry.context.toLowerCase()}`, entry)
	}

	for (const task of tasks) {
		for (const filePath of task.filesWrites) {
			// Try to find a matching Domain Mapping entry
			const matched = findMatchingEntry(filePath, domainEntries, byNameCtx)
			map.set(filePath, matched ? matched.action : 'create')
		}
	}
	return map
}

/**
 * Heuristic path → Domain Mapping entry matcher.
 * Checks if any entry's name appears in the file path AND context appears in the path.
 */
function findMatchingEntry(
	filePath: string,
	entries: DomainMappingEntry[],
	_byNameCtx: Map<string, DomainMappingEntry>,
): DomainMappingEntry | null {
	// Strict stem-exact match + path-segment hint per skill. The file's
	// basename (without extensions) must equal the Domain Mapping name's
	// leading identifier AND the path must contain the directory segment
	// expected for the entry's skill (e.g., a /controller entry only
	// matches paths under /controllers/). Disambiguates same-name entries
	// across layers — common in the /ui BFF context where controller and
	// query share the basename.
	const fileStem = stemOf(filePath)
	const lowerPath = filePath.toLowerCase()
	for (const entry of entries) {
		const id = identifierFromName(entry.name)
		if (fileStem !== id) continue
		const hint = SKILL_PATH_HINTS[entry.skill]
		if (hint && !hint.test(lowerPath)) continue
		return entry
	}
	return null
}

/**
 * Resolve whether a file path exists either in the graph or on disk.
 * For PR-18: a path is "resolvable" if:
 *   - It has one or more graph nodes (tracked artifact), OR
 *   - The file exists on disk (new file already written or pre-existing)
 */
function pathResolvable(filePath: string, ctx: ReturnType<typeof loadQueryContext>): boolean {
	// Check graph index
	const ids = ctx.index.byFile[filePath] ?? []
	if (ids.length > 0) return true
	// Check disk
	const abs = join(ROOT, filePath)
	return existsSync(abs)
}

// ── Skill matching for PR-20 ──

/**
 * Returns the expected skill name for a graph node kind.
 * Must match the COMPONENT_TO_SKILL mapping in review-query.ts.
 */
const KIND_TO_SKILL: Record<string, string> = {
	entity: 'entity',
	'value-object': 'value-object',
	enum: 'enum',
	'error-code': 'errors',
	usecase: 'usecase',
	'ui-query': 'query',
	event: 'event',
	'integration-event': 'event',
	handler: 'handler',
	controller: 'controller',
	middleware: 'controller',
	schema: 'schema',
	'zod-schema': 'schema',
	'repository-interface': 'repository',
	'repository-impl': 'repository',
	'service-interface': 'service',
	'service-impl': 'service',
	'db-table': 'db-modelling',
	'frontend-route': 'route',
	'frontend-section': 'component',
	'frontend-component': 'component',
	'frontend-dialog': 'component',
	'frontend-form': 'form',
	'frontend-ui-primitive': 'primitive',
	'frontend-store': 'store',
	'frontend-hook': 'component',
}

// ── Main validation entry point ──

export async function validatePlan(planPath: string): Promise<ValidationResult> {
	const findings: ValidationFinding[] = []

	// Load plan
	const absPath = planPath.startsWith('/') ? planPath : join(ROOT, planPath)
	if (!existsSync(absPath)) {
		return {
			exitCode: 1,
			findings: [
				{
					rule: 'PR-18',
					taskId: '(plan)',
					detail: `Plan file not found: ${planPath}`,
				},
			],
		}
	}

	const raw = readFileSync(absPath, 'utf8')
	const ast = parsePlan(raw)
	const domainEntries = parseDomainMapping(raw)

	// Load graph (non-fatal if unavailable — we'll skip graph-dependent checks)
	let ctx: ReturnType<typeof loadQueryContext> | null = null
	try {
		ctx = loadQueryContext()
	} catch {
		// Graph unavailable — PR-18 and PR-19 are graph-dependent, skip them
	}

	const pathActionMap = buildPathActionMap(ast.tasks, domainEntries)

	// ── PR-18: Non-new paths must resolve to an existing graph node ──
	if (ctx) {
		for (const task of ast.tasks) {
			if (task.status === 'done') continue
			for (const filePath of task.filesWrites) {
				const action = pathActionMap.get(filePath) ?? 'create'
				if (action === 'create') continue // new artifact — skip check
				// modify or read-only: path must be resolvable
				if (!pathResolvable(filePath, ctx)) {
					findings.push({
						rule: 'PR-18',
						taskId: task.id,
						detail: `Path in filesWrites is marked '${action}' in Domain Mapping but resolves to no graph node and does not exist on disk.`,
						path: filePath,
					})
				}
			}
		}
	}

	// ── PR-19: depends_on consistency with graph upstream edges ──
	if (ctx) {
		const adj = buildAdjacency(ctx.graph)

		// Build map: taskId → set of node ids written by that task
		const taskNodes = new Map<string, Set<string>>()
		for (const task of ast.tasks) {
			const nodeIds = new Set<string>()
			for (const filePath of task.filesWrites) {
				const ids = ctx.index.byFile[filePath] ?? []
				for (const id of ids) nodeIds.add(id)
			}
			taskNodes.set(task.id, nodeIds)
		}

		for (const task of ast.tasks) {
			if (task.status === 'done') continue
			if (task.dependsOn.length === 0) continue
			const taskWrittenNodes = taskNodes.get(task.id) ?? new Set()
			if (taskWrittenNodes.size === 0) continue // No graph nodes for this task — skip

			for (const depTaskId of task.dependsOn) {
				const depNodes = taskNodes.get(depTaskId) ?? new Set()
				if (depNodes.size === 0) continue // Dependency not in graph — skip

				// PR-19: For each node written by this task, check that at least one of
				// its upstream nodes is written by the dependency task.
				// We do a best-effort check: if ANY upstream overlap exists, the edge is valid.
				// We only flag if zero overlap AND both tasks have graph nodes.
				let anyOverlap = false
				for (const nodeId of taskWrittenNodes) {
					const inEdges = adj.in.get(nodeId) ?? []
					for (const edge of inEdges) {
						if (depNodes.has(edge.from)) {
							anyOverlap = true
							break
						}
					}
					if (anyOverlap) break
					// Also check transitive (shallow — 1 hop for now)
					const inEdges2 = adj.in.get(nodeId) ?? []
					for (const e of inEdges2) {
						const grandIn = adj.in.get(e.from) ?? []
						for (const ge of grandIn) {
							if (depNodes.has(ge.from)) {
								anyOverlap = true
								break
							}
						}
						if (anyOverlap) break
					}
					if (anyOverlap) break
				}

				// Only flag when both task and dependency have substantial graph nodes
				// and the overlap is clearly wrong. Skip if task writes scripts/* (not in graph).
				if (!anyOverlap && taskWrittenNodes.size > 0 && depNodes.size > 0) {
					findings.push({
						rule: 'PR-19',
						taskId: task.id,
						detail: `Task ${task.id} declares depends_on: ${depTaskId}, but no graph upstream edge was found between their written nodes.`,
					})
				}
			}
		}
	}

	// ── PR-20: skills list matches Domain Mapping skill column ──
	if (domainEntries.length > 0 && ctx) {
		// For each task, find which domain entries correspond to its filesWrites
		for (const task of ast.tasks) {
			if (task.status === 'done') continue
			for (const filePath of task.filesWrites) {
				// Test files are not first-class Domain Mapping artifacts —
				// they're co-created by the Task that owns the behavior. Skip
				// PR-20 for them; the fuzzy matcher can't distinguish a test
				// file from the artifact it tests when names overlap.
				if (/\.(test|spec)\.[jt]sx?$/.test(filePath)) continue
				const action = pathActionMap.get(filePath) ?? 'create'
				if (action === 'read-only') continue // read-only entries don't require a skill

				// Find the matching domain entry for this path
				const entry = findMatchingEntry(filePath, domainEntries, new Map())
				if (!entry) continue // no entry → skip (new artifact without Domain Mapping entry)

				// The skill from Domain Mapping (strip leading slash if any)
				const expectedSkill = entry.skill.replace(/^\//, '')

				// Check if the task's skills list includes the expected skill
				const taskSkills = task.skills.map(s => s.replace(/^\//, '').toLowerCase())
				if (!taskSkills.includes(expectedSkill.toLowerCase())) {
					// Also try matching via graph node kind
					const ids = ctx.index.byFile[filePath] ?? []
					let graphSkill: string | null = null
					for (const id of ids) {
						const node = ctx.graph.nodes.get(id)
						if (node) {
							graphSkill = KIND_TO_SKILL[node.kind] ?? null
							break
						}
					}

					const effectiveExpectedSkill = graphSkill ?? expectedSkill
					if (!taskSkills.includes(effectiveExpectedSkill.toLowerCase())) {
						findings.push({
							rule: 'PR-20',
							taskId: task.id,
							detail: `Task skills [${task.skills.join(', ')}] do not include '${effectiveExpectedSkill}' expected by Domain Mapping for path ${filePath}.`,
							path: filePath,
						})
					}
				}
			}
		}
	}

	// ── PR-21: modify tasks must cover transitiveDownstream ──
	// For bootstrap simplification: a modify artifact must have at least one Task touching it.
	// We flag when a 'modify' entry in Domain Mapping has zero tasks whose filesWrites
	// include the file, OR when no "ignore: downstream is unaffected" note is present.
	const modifyEntries = domainEntries.filter(e => e.action === 'modify')
	for (const entry of modifyEntries) {
		// Find tasks that write a file matching this entry (skipping done tasks)
		const covered = ast.tasks.some(
			task =>
				task.status !== 'done' &&
				task.filesWrites.some(fp => {
					const lp = fp.toLowerCase()
					return lp.includes(entry.name.toLowerCase()) && lp.includes(entry.context.toLowerCase())
				}),
		)
		if (!covered) {
			findings.push({
				rule: 'PR-21',
				taskId: '(plan)',
				detail: `Domain Mapping entry #${entry.index} (modify, ${entry.skill} ${entry.name} in ${entry.context}) has no Task covering it.`,
			})
		}
	}

	// ── PR-27: new frontend scaffoldable artifacts must be scaffolded via `bun cli` ──
	// A brand-new route/component/store/form/primitive under packages/app/** must have a
	// matching `bun cli <verb>` scaffold step in its Task (scaffold-then-write — the CLI owns
	// the canonical shape/folder/story). Modifying a file that already exists (graph or disk)
	// is exempt — only NET-NEW artifacts require scaffolding.
	for (const task of ast.tasks) {
		if (task.status === 'done') continue
		const taskBody = task.steps.map(s => s.body).join('\n')
		for (const filePath of task.filesWrites) {
			const verb = scaffoldableFrontendVerb(filePath)
			if (!verb) continue
			const inGraph = ctx ? (ctx.index.byFile[filePath]?.length ?? 0) > 0 : false
			if (inGraph || existsSync(join(ROOT, filePath))) continue // existing file → Modify, exempt
			if (!new RegExp(`bun cli\\s+${verb}\\b`).test(taskBody)) {
				findings.push({
					rule: 'PR-27',
					taskId: task.id,
					detail: `New frontend ${verb} '${filePath}' must be scaffolded with \`bun cli ${verb} …\` in the same Task (scaffold-then-write), not hand-authored.`,
					path: filePath,
				})
			}
		}
	}

	// ── PR-26: non-done Tasks with steps must declare filesWrites ──
	// /build cannot dispatch a Task whose files it doesn't know. If a Task is
	// pending and has TDD steps, it must enumerate the paths it will write.
	for (const task of ast.tasks) {
		if (task.status === 'done') continue
		if (task.steps.length === 0) continue
		if (task.filesWrites.length === 0) {
			findings.push({
				rule: 'PR-26',
				taskId: task.id,
				detail: `Task ${task.id} has ${task.steps.length} step(s) but no **Files to write:** declared. /build cannot dispatch without knowing the file scope.`,
			})
		}
	}

	return {
		exitCode: findings.length === 0 ? 0 : 1,
		findings,
	}
}

