function tokenizeTaskBody(body: string): PlanToken[] {
	const tokens: PlanToken[] = []

	const pathDecl = /(Create|Modify)[^\n]*?`([^`]+\.[tj]sx?)`/g
	let m: RegExpExecArray | null
	while ((m = pathDecl.exec(body)) !== null) {
		const mode = m[1]!.toLowerCase() === 'create' ? 'create' : 'modify'
		tokens.push({ kind: 'path', mode, path: m[2]!, offset: m.index })
	}

	const codeFence = /```(?:typescript|ts|tsx)\n([\s\S]*?)```/g
	while ((m = codeFence.exec(body)) !== null) {
		tokens.push({ kind: 'code', code: m[1]!, offset: m.index })
	}

	tokens.sort((a, b) => a.offset - b.offset)

