			stderr: 'inherit',
		},
	)
	const exitCode = await proc.exited

	rmSync(tmpRoot, { recursive: true, force: true })
	process.exit(exitCode)
}

if (import.meta.main) {
	main().catch(err => {
		console.error(err)
		process.exit(1)
	})
}

